function bestLineup(clubId,formation,readiness=false){
 const pool=squadPlayers(clubId);
 const remaining=pool.filter(p=>eligible(p.id));
 const slots=slotsFor(formation);
 const lineup=slots.map(pos=>{
  remaining.sort((a,b)=>(effectivePosition(b,pos)+(b.primary===pos?3:0)+(playerFitness(b.id)-80)*(readiness ? .3 : .05))-(effectivePosition(a,pos)+(a.primary===pos?3:0)+(playerFitness(a.id)-80)*(readiness ? .3 : .05)));
  const at=remaining.findIndex(p=>pos==='GK'?p.primary==='GK':p.primary!=='GK');const choice=at>=0?remaining.splice(at,1)[0]:null;return choice?.id||null;
 });
 remaining.sort((a,b)=>(b.overall+(playerFitness(b.id)-80)*.08)-(a.overall+(playerFitness(a.id)-80)*.08));
 const bench=pickBalancedBench(remaining,7);
 return {lineup,bench};
}
function pickBalancedBench(pool,count=7){
 const remaining=pool.filter(p=>eligible(p.id));
 const picks=[];for(const group of [['GK'],['CB','LB','RB'],['CM','DM','AM'],['ST','LW','RW']]){
  const candidates=remaining.filter(p=>group.some(pos=>positionRatio(p,pos)>=.75)).sort((a,b)=>b.overall-a.overall);
  const chosen=candidates[0];if(chosen){picks.push(chosen.id);remaining.splice(remaining.indexOf(chosen),1)}
 }
 remaining.sort((a,b)=>b.overall-a.overall);picks.push(...remaining.slice(0,Math.max(0,count-picks.length)).map(p=>p.id));return Array.from({length:count},(_,i)=>picks[i]||null)
}
