 if(!id||minutes<=0)return;recordLoanMinutes(career,id,minutes,rating);
 if(isCup(statsCompetition)){const key=statsCompetition===UC_ID?'ucPlayedFor':statsCompetition===CL_ID?'clPlayedFor':statsCompetition===FA_ID?'faPlayedFor':'cupPlayedFor';career[key]??={};career[key][id]??=owner(id);}
