let dragFrame=0;
function clearTouchDrag(){const pointer=activeDrag?.pointer;activeDrag=null;cancelAnimationFrame(dragFrame);dragFrame=0;dragGhost?.remove();dragGhost=null;dragTarget=null;document.body.classList.remove('shirt-dragging');document.querySelectorAll('.drag-preview,.touch-drag-ghost').forEach(n=>n.remove());document.querySelectorAll('.drop-highlight').forEach(n=>n.classList.remove('drop-highlight'));if(pointer!==undefined&&root.hasPointerCapture?.(pointer))root.releasePointerCapture(pointer)}
function dragHit(){if(!activeDrag)return;const slot=document.elementFromPoint(activeDrag.cx,activeDrag.cy)?.closest('[data-drop-slot],[data-drop-player],[data-live-drop]');if(slot!==dragTarget){dragTarget?.classList.remove('drop-highlight');dragTarget=slot;slot?.classList.add('drop-highlight')}}
function dragScrollChain(start){const chain=[];for(let el=start;el&&el!==document.body;el=el.parentElement)if(el.scrollHeight>el.clientHeight+2&&/(auto|scroll)/.test(getComputedStyle(el).overflowY))chain.push(el);return chain}
function dragVisibleBounds(panel){const r=panel.getBoundingClientRect();let top=Math.max(0,r.top),bottom=Math.min(innerHeight,r.bottom);for(let el=panel.parentElement;el&&el!==document.body;el=el.parentElement)if(/auto|scroll|hidden|clip/.test(getComputedStyle(el).overflowY)){const b=el.getBoundingClientRect();top=Math.max(top,b.top);bottom=Math.min(bottom,b.bottom)}return {top,bottom}}
function scrollDrag(){if(!activeDrag?.moved)return;const over=document.elementFromPoint(activeDrag.cx,activeDrag.cy),chain=[...new Set([...dragScrollChain(over),...dragScrollChain(activeDrag.panel)])];for(const panel of chain){const {top,bottom}=dragVisibleBounds(panel);if(bottom-top<16)continue;const edge=Math.min(56,(bottom-top)*.22),cy=activeDrag.cy;let delta=cy<top+edge?-Math.min(16,Math.max(2,(top+edge-cy)/3)):cy>bottom-edge?Math.min(16,Math.max(2,(cy-bottom+edge)/3)):0;if(!delta)continue;const old=panel.scrollTop;panel.scrollTop+=delta;if(panel.scrollTop!==old){dragHit();break}}dragFrame=requestAnimationFrame(scrollDrag)}
root.addEventListener('pointerdown',event=>{if(activeDrag)clearTouchDrag();if(event.pointerType==='mouse'||event.target.closest('.slot-tool,.bench-target'))return;const card=event.target.closest('.player-card[data-player],.shirt-slot[data-player],.live-player-card[draggable="true"],.sub-player[draggable="true"],.selection-row[draggable="true"]');if(!card?.dataset.player||!event.target.closest('.shirt'))return;let panel=card.parentElement;while(panel&&!(panel.scrollHeight>panel.clientHeight+8&&/(auto|scroll)/.test(getComputedStyle(panel).overflowY)))panel=panel.parentElement;activeDrag={id:card.dataset.player,x:event.clientX,y:event.clientY,cx:event.clientX,cy:event.clientY,pointer:event.pointerId,panel,moved:false,handle:!!event.target.closest('.shirt')};});
document.addEventListener('pointermove',event=>{if(!activeDrag||event.pointerId!==activeDrag.pointer)return;activeDrag.cx=event.clientX;activeDrag.cy=event.clientY;if(!activeDrag.moved&&Math.hypot(event.clientX-activeDrag.x,event.clientY-activeDrag.y)<9)return;if(!activeDrag.moved&&!activeDrag.handle&&Math.abs(event.clientY-activeDrag.y)>Math.abs(event.clientX-activeDrag.x)*1.5){clearTouchDrag();return}event.preventDefault();if(!activeDrag.moved){activeDrag.moved=true;try{root.setPointerCapture(event.pointerId)}catch{}document.body.classList.add('shirt-dragging');dragGhost=document.createElement('div');dragGhost.className='touch-drag-ghost';dragGhost.innerHTML=shirt(player(activeDrag.id));document.body.appendChild(dragGhost);dragFrame=requestAnimationFrame(scrollDrag)}dragGhost.style.left=event.clientX+'px';dragGhost.style.top=event.clientY+'px';dragHit();},{passive:false});
