function notificationGroups(){
 if(!career)return [];const read=new Set(career.noticeRead||[]),groups=new Map();
 const add=(group,key,label,target,id)=>{if(read.has(key)||!notifyEnabled(group))return;let item=groups.get(group);if(!item)groups.set(group,item={group,label,target,id,keys:[]});item.keys.push(key)};
 for(const n of career.news||[])if(isCup(n.action)&&n.important)add(n.action,'cup-news:'+career.news.indexOf(n),cupName(n.action)+(n.kind==='cup-draw'?' draw':' update'),n.action);
 for(const n of career.news||[])if(['club-story','stadium-booking'].includes(n.kind))add('club-life','life-news:'+career.news.indexOf(n),'Club life & stadium events','club-life');
 for(const f of career.friendlyInvitations||[])if(f.status==='offered'&&f.date>=career.date)add('friendlies',f.id,'Pre-season invitations','friendlies');
 for(const o of career.offers||[])if(['new','counter'].includes(o.status))add('offers',`offer:${o.id}:${o.clubId}:${o.fee}:${o.status}`,'Transfer offer','transfers',o.id);
 for(const c of career.conversations||[])if(c.status==='new')add('requests','conversation:'+c.key,'Player request','conversations',c.id);
 for(const p of squadPlayers(career.clubId)){const state=career.players[p.id];if(state.injuryDays>0){const at=career.news.findLastIndex(n=>n.text.includes(p.name)&&/knock|injur|strain|sprain|ligament/i.test(n.text));add('injuries',`injury:${p.id}:${state.injuryType}:${at}`,'Injury update','profiles',p.id)}if(state.suspensionMatches>0){const at=career.news.findLastIndex(n=>n.text.includes(p.name)&&/Suspended/.test(n.text));add('suspensions',`suspension:${p.id}:${at}`,'Suspension update','lineup',p.id)}if(state.request){const at=career.news.findLastIndex(n=>n.text.includes(p.name)&&/loan|transfer/i.test(n.text));add('roles',`request:${p.id}:${state.request}:${at}`,'Squad request','lineup',p.id)}}
 (career.news||[]).forEach((n,i)=>{const key='news:'+i+':'+n.date;if(n.kind==='season-summary'&&n.season===career.seasonReviews?.at(-1)?.season)add('season-summary',key,'Season review ready','season-summary',n.season);if(n.important&&['board','supporters','season-review'].includes(n.kind))add(n.action==='finances'?'board-finances':n.kind,key,n.kind==='season-review'?'League and board review':n.kind==='supporters'?'Supporter concern':'Board update',n.action==='finances'?'board-finances':'expectations');if(['contracts','coverage'].includes(n.kind)&&(n.kind==='contracts'?squadPlayers(career.clubId).some(p=>contractStatus(career,p).expiring):squadCover(career,squadPlayers(career.clubId),slotsFor(career.formation)).filled<11)&&i===career.news.findLastIndex(x=>x.kind===n.kind))add(n.kind,key,n.kind==='contracts'?'Contract review':'Squad cover warning',n.kind);if(n.kind==='wages'&&i===career.news.findLastIndex(x=>x.kind==='wages'))add('wages',key,`Weekly wages: ${fmtMoney(n.amount)} · ${fmtDate(n.date)} · Balance ${fmtMoney(n.balance)}`,'finances');if(n.kind==='scouting'&&n.fixtureDate===nextFixture()?.date)add('scouting',key,'Opponent scouting report','scouting',n.clubId);if(['development','youth','stadium','training'].includes(n.kind)&&(n.kind!=='training'||i===career.news.findLastIndex(x=>x.kind==='training')))add(n.kind,key,n.kind==='stadium'?'Stadium update':n.kind==='youth'?'Youth report':n.kind==='training'?'Training report':'Development report',n.kind==='stadium'?'facilities':n.kind);});
 const priority={'league-cup':1,'club-life':2,offers:0,injuries:1,suspensions:1,'board-finances':1,'season-review':1,'season-summary':0,requests:2,roles:2,board:2,supporters:2,stadium:3,development:4,youth:5,scouting:6,wages:7};return [...groups.values()].sort((a,b)=>(priority[a.group]??5)-(priority[b.group]??5));
}
