function openNotification(group){const n=notificationGroups().find(x=>x.group===group);if(!n)return;if(n.target==='season-summary'){career.noticeRead=[...new Set([...(career.noticeRead||[]),...n.keys])];openSeasonReview(n.id);return}if(isCup(n.target)){career.noticeRead=[...new Set([...(career.noticeRead||[]),...n.keys])];careerPanelOpen=true;section='organiser';sub=n.target;cupSelectedRound=null;save();render();return}if(n.target==='club-life'){markClubLifeRead();careerPanelOpen=true;section='organiser';sub='events';save();render();return}if(['expectations','board-finances','contracts','coverage'].includes(n.target)){career.noticeRead=[...new Set([...(career.noticeRead||[]),...n.keys])];save();openNewsTarget(n.target==='board-finances'?'finances':n.target);return}if(n.target==='friendlies'){careerPanelOpen=true;section='hub';career.noticeRead=[...new Set([...(career.noticeRead||[]),...n.keys])];save();render();return;}if(n.target==='scouting'){career.noticeRead=[...new Set([...(career.noticeRead||[]),...n.keys])];browsedClub=n.id;scoutedPlayer=null;clubReturnFixture=false;save();render();return;}career.noticeRead=[...new Set([...(career.noticeRead||[]),...n.keys])];careerPanelOpen=true;section=['facilities','finances'].includes(n.target)?n.target:'squad';sub=['facilities','finances'].includes(n.target)?'lineup':n.target;instructionPlayer=null;if(n.id)selectedPlayer=n.id;if(n.target==='lineup'&&n.id){instructionPlayer=n.id;instructionAnchorType='shirt-slot'}save();render();const row=n.id?document.querySelector(`[data-action="accept-offer"][data-id="${n.id}"]`):null;row?.scrollIntoView({block:'center'});}
let historyMoving=false;
function navigationDepth(){if(streamDecisionOpen||streamBudgetOpen)return 3;if(view==='career'&&career?.ui?.seasonReview?.open&&!match)return 3;if(view==='career'&&career?.ui?.ownerWelcome?.open&&!match)return 3;if(navOpen||noticesOpen)return (careerPanelOpen?2:1)+1;if(pendingRestore)return view==='title'?2:4;if(view==='title')return titleOptionsOpen?1:0;if(view==='mode'||view==='setup')return 1;if(matchExitOpen)return 3;if(match?.phase==='live'&&(match.inspectPlayer||match.drawerOpen))return match.inspectPlayer&&match.drawerOpen?4:3;if(match||postMatchTable||career.matchday||pendingDraw(career))return 2;let depth=careerPanelOpen?2:1;if(careerPanelOpen&&!['lineup','table'].includes(sub))depth++;if((renewalPlayer&&careerPanelOpen&&section==='finances'&&sub==='contracts')||transferReview||fundingReview||selectionPreview||instructionPlayer||opponentOpen||reportIndex!==null||archivedReport||browsedClub)depth++;if(scoutedPlayer)depth++;if(focusMode&&careerPanelOpen&&!match)depth++;return depth;}
function syncNavigation(){if(historyMoving)return;const depth=navigationDepth(),current=history.state?.clublineDepth??0;if(depth<current){historyMoving=true;history.go(depth-current);return}for(let i=current+1;i<=depth;i++)history.pushState({clublineDepth:i},'');history.replaceState({clublineDepth:depth},'');}
function syncMatchExit(){document.querySelector('.match-exit-overlay')?.remove();if(!matchExitOpen||view!=='career')return;root.insertAdjacentHTML('beforeend',`<div class="overlay match-exit-overlay" role="dialog" aria-modal="true" aria-label="Leave match"><div class="modal"><h2>Match paused</h2><p>Your match will be saved if you return to the main menu.</p><div class="modal-actions"><button class="btn primary" data-action="match-return">Return to match</button><button class="btn" data-action="match-menu">Main menu</button></div></div></div>`);}
function returnToMatch(){matchExitOpen=false;if(match?.phase==='live'){match.paused=matchReturnState?.paused||false;match.pauseReason=matchReturnState?.reason||'manual';}save();render();}
function appBack(){
 if(boardReviewOpen){boardReviewOpen=null;render();return;}

 if(streamDecisionOpen){streamDecisionOpen=null;render();return;}if(streamBudgetOpen){streamBudgetOpen=false;render();return;}if(view==='mode'){view='title';render();return;}
 if(outcomeCard){outcomeCard=null;render();return;}
 if(view==='career'&&career?.ui?.seasonReview?.open&&!match){career.ui.seasonReview.open=false;save();render();return}
 if(view==='career'&&!match&&career.matchday&&career.matchday.phase!=='await-match'){continueMatchday();return}
 if(view==='career'&&!isStreamlined()&&!match&&!career.matchday&&pendingDraw(career)&&drawFlowOpen&&!career.ui.ownerWelcome?.open&&!career.ui.ownerWelcome?.returnTo){finishDrawEvent();return}
 if(view==='career'&&career?.ui?.ownerWelcome?.open&&!match){career.ui.ownerWelcome.open=false;career.ui.ownerWelcome.returnTo=false;careerPanelOpen=false;save();render();return}
 if(navOpen||noticesOpen){navOpen=false;noticesOpen=false;syncWorkspaceControls();syncNavigation();return}
 if(pendingRestore){pendingRestore=null;render();return}
 if(renewalPlayer&&careerPanelOpen&&section==='finances'&&sub==='contracts'){renewalPlayer=null;render();return}
 if(selectionPreview){selectionPreview=null;render();return}
 if(fundingReview){fundingReview=null;render();return}
 if(transferReview){transferReview=null;render();return}
 if(titleOptionsOpen){titleOptionsOpen=false;render();return}
 if(scoutedPlayer){scoutedPlayer=null;const panel=document.querySelector('[data-club-detail]');if(panel)panel.innerHTML='';syncNavigation();return}
 if(browsedClub){closeClubBrowser();return}
 if(matchExitOpen){returnToMatch();return}
 if(match?.phase==='live'&&match.inspectPlayer){match.inspectPlayer=null;save();render();return}
 if(match?.phase==='live'&&match.drawerOpen){setMatchDrawer(false);return}
 if(instructionPlayer){closePlayerDetails();return}
 if(reportIndex!==null||archivedReport){reportIndex=null;archivedReport=null;render();return}
 if(opponentOpen){opponentOpen=false;render();return}
 if(view==='career'&&match){if(match.phase==='live'){matchReturnState={paused:match.paused&&!['goal','yellow'].includes(match.pauseReason),reason:match.pauseReason};clearTimeout(autoResumeTimer);match.paused=true;match.pauseReason='manual';matchExitOpen=true;save();render();return}if(match.phase==='report'){closeMatchReport();return}if(match.phase==='confirm'){match.phase='choice';render();return}match=null;if(career.matchday)career.matchday.phase='await-match';career.time='09:00';save();render();return}
 if(view==='career'&&!match&&career.ui.ownerWelcome?.returnTo){career.ui.ownerWelcome.returnTo=false;career.ui.ownerWelcome.open=true;careerPanelOpen=false;navOpen=false;noticesOpen=false;save();render();return}
 if(postMatchTable){postMatchTable=false;section='hub';careerPanelOpen=true;render();return}
 if(focusMode&&careerPanelOpen&&!match){focusMode=false;syncWorkspaceControls();syncNavigation();return}
 if(view==='career'&&careerPanelOpen){const group=navigationGroup();if(group==='club'&&section!=='club'){openRoute('club');return;}if(group==='inbox'&&section!=='inbox'){openRoute('inbox');return;}if(section==='organiser'&&sub!=='overview'){openRoute('organiser','overview');return;}if(section==='squad'&&sub!=='lineup'){openRoute('squad','lineup');return;}careerPanelOpen=false;render();return}
 if(view!=='title'){view='title';render();}
}
history.replaceState({clublineDepth:0},'');
window.addEventListener('popstate',event=>{if(!historyMoving&&view==='title'&&!titleOptionsOpen&&event.state?.clublineDepth!=null){history.back();return}if(historyMoving){historyMoving=false;history.replaceState({clublineDepth:navigationDepth()},'');return}appBack();});

render();

if('serviceWorker' in navigator&&location.protocol==='https:')window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').then(reg=>reg.update()).catch(()=>{}));

function financeOutlook(){
 const weekly=weeklyWages(),next=new Date(career.date+'T12:00:00Z');next.setUTCDate(next.getUTCDate()+((8-next.getUTCDay())%7||7));
 const commercial=myClub().commercialWeekly||0;
 const wageBills=(career.news||[]).filter(n=>['wages','offseason-finance'].includes(n.kind)),home=career.reports.filter(r=>r.home),revenue=home.reduce((n,r)=>n+(r.tickets||0)+(r.concessions||0)+(r.shop||0),0),costs=home.reduce((n,r)=>n+(r.operating||0),0),forecast=career.balance-4*(weekly-commercial);
 return `<div class="detail-row"><span>Home gross revenue · season</span><b>${fmtMoney(revenue)}</b></div><div class="detail-row"><span>Home operating costs · season</span><b>${fmtMoney(costs)}</b></div><h3>Payroll and outlook</h3><div class="detail-row"><span>Weekly commercial income</span><b>${fmtMoney(commercial)}</b></div><p>Wages are deducted every Monday when time advances. Next payroll: ${fmtDate(next.toISOString().slice(0,10))} · ${fmtMoney(weekly)}.</p><div class="detail-row"><span>Four weekly payrolls</span><b>${fmtMoney(4*weekly)}</b></div><div class="detail-row"><span>Balance after four payrolls</span><b class="${forecast<0?'status-red':''}">${fmtMoney(forecast)}</b></div><p>${forecast<0?'Current cash will not cover four payrolls. Review spending and your squad.':'This forecast subtracts wages only; future match income, transfers and investment are excluded.'}</p><p>Funding and upgrades are paid on confirmation; they are not charged again each Monday. Matchday operating costs are deducted from home revenue in each report.</p>${wageBills.length?`<details><summary>Recent wage payments</summary>${wageBills.slice(-6).reverse().map(n=>`<p>${fmtDate(n.date)} · ${fmtMoney(n.amount)} paid · Balance ${fmtMoney(n.balance)}</p>`).join('')}</details>`:''}`;
}

function simulateMinute(){simulationBatch=true;try{tickMatch(true)}finally{simulationBatch=false}}

function ensureAttendance(){if(!match)return;const seats=matchVenue().capacity;if(!Number.isFinite(match.occupancy))match.occupancy=match.friendly?.25+Math.random()*.15:match.neutral?(matchVenue().national?.9+Math.random()*.09:.78+Math.random()*.15):.51+Math.random()*.35;if(!Number.isFinite(match.attendance))match.attendance=Math.round(seats*match.occupancy)}

function isClubNews(n){if(n.kind==='manager-change')return n.clubId===career.clubId;if(n.kind==='scouting'||n.reportDate)return true;if(n.playerId)return n.clubId?n.clubId===career.clubId:owner(n.playerId)===career.clubId;return !!n.kind||n.text.includes(clubName(career.clubId))||squadPlayers(career.clubId).some(p=>n.text.includes(p.name))}
function openNewsTarget(target){if(!['expectations','finances','contracts','coverage','training'].includes(target))return;careerPanelOpen=true;renewalPlayer=null;section=['coverage','training'].includes(target)?'squad':['finances','contracts'].includes(target)?'finances':'hub';sub=['contracts','coverage','training'].includes(target)?target:'lineup';instructionPlayer=null;render();if(target==='expectations'){const card=document.querySelector('.season-expectations');if(card){card.open=true;card.scrollIntoView({block:'nearest'})}}}
function expectationsCard(){
 const a=assessSeason(career,ownLeague(),standings()),latest=career.boardReviews.at(-1);
 const indicator=(label,band,score,reasons)=>`<details class="confidence-detail"><summary><span>${label}</span><b class="status-chip ${band.tone}">${band.label}</b></summary><p>${score}/100 · ${reasons.map(html).join(' ')}</p></details>`;
 const review=r=>`<div class="season-review"><h3>Season ${r.season} review</h3><p>Finished ${r.position} · ${r.points} points · Balance ${fmtMoney(r.balance)}</p>${r.objectives.map(o=>`<div class="objective-row"><span>${html(o.title)}</span><b class="status-chip ${o.tone}">${html(o.status)}</b></div>`).join('')}<p>Board: ${r.boardBand.label} · Supporters: ${r.supporterBand.label}</p></div>`;
 return `<details class="season-expectations"><summary><span>Season ${career.season} expectations</span><small>Top ${career.expectations.targetPosition} · Healthy finances</small></summary><p>Targets are set from your club’s starting strength and stay fixed for this season. Your confidence is advisory; other clubs can change managers. Formal board reports arrive quarterly, or monthly while concerns persist.</p>${a.objectives.map(o=>`<div class="objective-row"><span><b>${html(o.title)}</b><small>${html(o.detail)}</small></span><b class="status-chip ${o.tone}">${html(o.status)}</b></div>`).join('')}<div class="hero-actions"><button class="btn slim ghost" data-action="news-review" data-target="finances">Review finances →</button><button class="btn slim ghost" data-action="section" data-section="squad">Review squad →</button></div>${a.complete&&latest?.season===career.season?review(latest):''}${career.boardReviews.filter(r=>r.season!==career.season).length?`<details><summary>Previous season reviews</summary>${career.boardReviews.filter(r=>r.season!==career.season).slice().reverse().map(review).join('')}</details>`:''}</details><div class="confidence-grid">${indicator('Board',a.boardBand,a.board,a.boardReasons)}${indicator('Supporters',a.supporterBand,a.supporters,a.supporterReasons)}</div>`;
}

function friendlyInvitationsPanel(){const invites=(career.friendlyInvitations||[]).filter(x=>x.status==='offered'&&x.date>=career.date);if(!invites.length)return '';return `<section class="friendly-invitations"><h3>Pre-season invitations</h3>${invites.map(f=>{const estimate=friendlyEstimate(career,myClub(),f);return `<article class="friendly-invitation"><b>${html(clubName(f.opponent))} · ${f.home?'Home':'Away'}</b><p>${fmtDate(f.date)} · 15:00 · Friendly</p><small>${f.home?'Estimated net match income '+fmtMoney(estimate.income):'Travel cost '+fmtMoney(estimate.travel)} · Condition and injury risk apply</small><div class="friendly-actions"><button class="btn slim" data-action="accept-friendly" data-id="${f.id}">Accept</button><button class="btn slim ghost" data-action="decline-friendly" data-id="${f.id}">Decline</button></div></article>`}).join('')}</section>`;}

function beginNextSeason(){settleOtherFixtures();if(!seasonReady(career)||nextFixture()||match||postMatchTable){toast('Complete all divisions, playoffs and cup competitions first. Advance time from Home.');return;}const seasonEnd=Number(career.seasonStart.slice(0,4))+1;const restart=seasonEnd+'-08-03';if(career.clubLife.bookings.some(b=>b.status==='accepted'&&bookingWindow(b).end>=restart)){toast('Complete or cancel stadium bookings that extend into the new season first.');return}save();career.ui.seasonReview??={season:career.season,open:false};career.ui.seasonReview.open=false;updateExpectations(career,ownLeague(),standings());const year=Number(career.seasonStart.slice(0,4))+1;for(const p of career.prospects.filter(p=>p.calledUp))returnProspect(career,source,p.id);settleClubLifeOffSeason(year+'-08-03');settleOffSeason(year+'-08-03');career.clQualified=clQualified(career,source,year);career.ucQualified=ucQualified(career,source,year,career.clQualified);career.news.push({date:restart,kind:'europe-qualification',important:true,text:career.clQualified.includes(career.clubId)?'Your club qualify for next season’s Champions League.':career.ucQualified.clubs.includes(career.clubId)?'Your club qualify for next season’s UEFA Cup through '+career.ucQualified.routes[career.clubId]+'.':'European qualification is confirmed for next season.',action:career.clQualified.includes(career.clubId)?CL_ID:UC_ID});rolloverDivisions(career,source,clubName);rolloverDevelopment(career,source,year+'-08-03');initialiseFreeAgents(career,source);settleFutureTransfers();browsedDivision=null;initialiseWagePlan(career,squadPlayers(career.clubId));resetTrainingSeason();resetSeasonCards(career);career.scoutingFunding=0;advanceConstruction(career);career.schedule=scheduleSeason(year);rolloverCup(career,source,clubName);rolloverFA(career,source);rolloverCL(career,source);rolloverUC(career,source);career.cupStats={};career.cupPlayedFor={};career.faStats={};career.faPlayedFor={};career.matchday=null;career.matchdaySeen=[];cupSelectedRound=null;offerFriendlies(career,source);calendarMonth=null;calendarDay=null;career.reports=[];career.offers=[];updateExpectations(career,ownLeague(),standings());career.time='09:00';career.transferList=career.transferList.filter(id=>!career.players[id]?.retired);const picks=bestLineup(career.clubId,career.formation);career.lineup=picks.lineup;career.bench=picks.bench;developmentDay(career,source,nextFixture());trainingDay(career,source,nextFixture());prepareScoutingReport();prepareManagementReminders();drawFlowOpen=false;career.ui.ownerWelcome={open:true,visited:[],dismissed:false};initialiseNationalities(career,source);initialiseManagers(career,source);if(isStreamlined())initialiseStreamlined(true);section='hub';sub='lineup';save();render()}
function settleOffSeason(newStart){const start=career.date;let wages=0,income=0,weeks=0;for(let date=addDays(start,1);date<=newStart;date=addDays(date,1)){career.date=date;settleFutureTransfers();loanDay(career,source);if(new Date(date+'T12:00:00Z').getUTCDay()===1){const payroll=weeklyWages(),commercial=myClub().commercialWeekly||0;wages+=payroll;income+=commercial;weeks++;career.balance+=commercial-payroll;}if(addDays(date,1).slice(0,7)!==date.slice(0,7))runManagerDay();}career.date=start;if(weeks)career.news.push({date:newStart,kind:'offseason-finance',amount:wages,commercial:income,text:`Off-season accounts: ${weeks} payrolls, ${fmtMoney(wages)} wages and ${fmtMoney(income)} commercial income. Net ${income>=wages?'+':'−'}${fmtMoney(Math.abs(income-wages))}.`});const elapsed=Math.round((Date.parse(newStart)-Date.parse(start))/86400000);for(const state of Object.values(career.players)){state.injuryDays=Math.max(0,(state.injuryDays||0)-elapsed);if(!state.injuryDays)state.injuryType=null;}}


root.addEventListener('click',event=>{if(event.target.closest('.manager-checklist>summary')){career.ui.checklistExpanded=!event.target.closest('.manager-checklist').open;save();}},true);
let clubSwipe=null,clubSwipeClickUntil=0;
root.addEventListener('touchstart',event=>{if(view!=='setup'||event.touches.length!==1||event.target.closest('input,textarea,select,[contenteditable]')){clubSwipe=null;return}const t=event.touches[0];clubSwipe={x:t.clientX,y:t.clientY,at:Date.now(),scroll:window.scrollY};},{passive:true});
root.addEventListener('touchmove',event=>{if(!clubSwipe)return;if(event.touches.length!==1){clubSwipe=null;return}const t=event.touches[0],dx=t.clientX-clubSwipe.x,dy=t.clientY-clubSwipe.y;if(Math.abs(dy)>20&&Math.abs(dy)>Math.abs(dx)*.7){clubSwipe=null;return}if(Math.abs(dx)>20&&Math.abs(dx)>Math.abs(dy)*1.5)event.preventDefault();},{passive:false});
root.addEventListener('touchcancel',()=>{clubSwipe=null;},{passive:true});
root.addEventListener('touchend',event=>{const start=clubSwipe;clubSwipe=null;if(view!=='setup'||!start||event.touches.length||!event.changedTouches[0])return;const t=event.changedTouches[0],dx=t.clientX-start.x,dy=t.clientY-start.y;if(Math.abs(dx)<60||Math.abs(dx)<Math.abs(dy)*1.5||Date.now()-start.at>1200)return;const clubs=setupClubsAlphabetically(),at=clubs.findIndex(x=>x.id===setup.clubId);setup.clubId=clubs[(at+(dx<0?1:-1)+clubs.length)%clubs.length].id;setup.colour=null;clubSwipeClickUntil=Date.now()+500;render();window.scrollTo(0,start.scroll);},{passive:true});
root.addEventListener('click',event=>{if(Date.now()<clubSwipeClickUntil){event.preventDefault();event.stopImmediatePropagation();}},true);

function openSeasonReview(season){
 if(match||postMatchTable||career.matchday){toast('Finish the matchday screens before opening the season review.');return}
 save();const r=career.seasonReviews?.find(r=>r.season===season);if(!r){toast('The full season review is available after every competition and playoff has finished.');return}
 career.ui.seasonReview={open:true,season};career.ui.ownerWelcome.open=false;notificationsExpanded=false;save();render();
}
function seasonReviewCard(){const r=career.seasonReviews?.at(-1);return r?`<div class="owner-welcome-card"><div><h3>${html(r.label)} season review</h3><p>${html(r.league.movement)} · ${r.league.position} in ${html(divisionInfo(r.league.division).name)}</p></div><button class="btn slim" data-action="open-season-review" data-season="${r.season}">Review →</button></div>`:'';}
function seasonReviewArchive(){return `<h3>Completed season reviews</h3><p>Final results, prizes, board verdict and confirmed English European places are saved at the end of each season.</p><div class="list">${(career.seasonReviews||[]).slice().reverse().map(r=>`<button class="row" data-action="open-season-review" data-season="${r.season}"><span><b>${html(r.label)} · ${html(r.clubName)}</b><small>${html(divisionInfo(r.league.division).name)} · Position ${r.league.position} · ${html(r.league.movement)}</small></span><span>Review →</span></button>`).join('')||'<p>Finish all competitions and playoffs to create your first review.</p>'}</div>`;}
function seasonReviewOverlay(){
 const state=career.ui.seasonReview;if(!state?.open||match)return '';const r=career.seasonReviews?.find(r=>r.season===state.season);if(!r)return '';const next=r.nextSeason;
 const qualifiers=(rows)=>rows.map(x=>`<div class="row"><span>${html(x.name)}<small>${html(x.route)}</small></span></div>`).join('');
 const finalTable=(id)=>`<details><summary>${html(divisionInfo(id).name)} final table</summary><div class="review-table-wrap"><table><thead><tr><th>#</th><th>Club</th><th>P</th><th>GD</th><th>Pts</th></tr></thead><tbody>${r.tables[id].map((x,i)=>`<tr class="${x.id===r.clubId?'mine':''}"><td>${i+1}</td><td>${html(x.name)}</td><td>${x.P}</td><td>${x.GD}</td><td>${x.Pts}</td></tr>`).join('')}</tbody></table></div></details>`;
 return `<div class="overlay season-summary-overlay" role="dialog" aria-modal="true" aria-labelledby="season-summary-title"><div class="modal season-summary-modal"><div class="modal-head"><div><span class="eyebrow">Completed season / ${html(r.label)}</span><h2 id="season-summary-title">${html(r.clubName)}</h2></div><button class="btn slim" data-action="season-review-close" aria-label="Close season review">Close ×</button></div><h3>${html(divisionInfo(r.league.division).name)} · Position ${r.league.position} of ${r.league.size}</h3><p>${r.league.Pts} points · ${r.league.P} played · Goal difference ${r.league.GD>=0?'+':''}${r.league.GD}</p><p><b>${html(r.league.movement)}</b> · Next season: ${html(divisionInfo(next.division).name)}</p><section><h3>Cup outcomes</h3><div class="list">${r.competitions.map(x=>`<div class="row"><span><b>${html(x.title)}</b><small>${html(x.outcome)}${x.winner?' · Winners: '+html(x.winner.name):''}</small></span></div>`).join('')}</div></section><section><h3>Board verdict · ${html(r.board.boardBand.label)}</h3><p>Confidence ${r.board.board}/100 · Supporters: ${html(r.board.supporterBand.label)}</p>${r.board.objectives.map(o=>`<div class="objective-row"><span>${html(o.title)}</span><b class="status-chip ${html(o.tone)}">${html(o.status)}</b></div>`).join('')}<details><summary>Assessment details</summary>${r.board.boardReasons.map(t=>`<p>${html(t)}</p>`).join('')}<p>Uses the existing league and financial assessment; cup outcomes are shown separately.</p></details></section><section><h3>Prize money already received · ${fmtMoney(r.prizeReceived)}</h3><div class="list">${r.prizes.map(p=>`<div class="row"><span>${html(p.name)}${p.due?'<small>Still due: '+fmtMoney(p.due)+'</small>':''}</span><b>${fmtMoney(p.received)}</b></div>`).join('')}</div><p>Club balance at review: <b>${fmtMoney(r.balance)}</b>. Prizes are game estimates and are already included in this balance. Reviewing this page pays nothing again. Off-season wages and income are settled when next season begins.</p></section><section><h3>Confirmed English European qualifiers</h3><details open><summary>Champions League · ${r.qualifiers.cl.length} clubs</summary>${qualifiers(r.qualifiers.cl)}</details><details open><summary>UEFA Cup · ${r.qualifiers.uc.length} clubs</summary>${qualifiers(r.qualifiers.uc)}</details><p>Foreign entrants are selected from the country pools when next season begins.</p></section><section><h3>Your ${html(next.label)} entries</h3><p>${html(divisionInfo(next.division).name)}, FA Cup and League Cup.${next.entry?' '+html(cupName(next.entry))+' · '+html(next.route)+'.':' No European qualification.'}</p><details><summary>European formats next season</summary><p><b>Champions League:</b> ${html(next.formats.championsLeague)}</p><p><b>UEFA Cup:</b> ${html(next.formats.uefaCup)}</p></details>${next.formats.changes.map(x=>`<p class="decision-note"><b>Format update:</b> ${html(x.text)}</p>`).join('')}</section><section><h3>Promotion and relegation</h3>${['first','second'].map(id=>`<p><b>Promoted from ${html(divisionInfo(id).name)}:</b> ${r.movement.promoted[id].map(x=>html(x.name)).join(', ')}</p>`).join('')}${['premier','first'].map(id=>`<p><b>Relegated from ${html(divisionInfo(id).name)}:</b> ${r.movement.relegated[id].map(x=>html(x.name)).join(', ')}</p>`).join('')}${['premier','first','second'].map(finalTable).join('')}</section><div class="modal-actions"><button class="btn" data-action="season-review-close">Return to club</button>${r.season===career.season&&seasonReady(career)?'<button class="btn primary" data-action="season-review-continue">Begin next season →</button>':''}</div></div></div>`;
}

function syncSelectionUI(){
 for(const el of root.querySelectorAll('.shirt-slot,.player-card,.selection-row')){
  const selected=selectedPlayer?el.dataset.player===selectedPlayer:selectedSlot!==null&&Number(el.dataset.dropSlot)===selectedSlot;
  el.classList.toggle('selected',!!selected);el.classList.toggle('active',!!selected);
  el.classList.toggle('swap-target',!!selectedPlayer&&el.dataset.player!==selectedPlayer&&(el.dataset.dropSlot!==undefined||el.dataset.dropPlayer!==undefined));
 }
 const status=root.querySelector('[data-selection-status]');if(status)status.textContent=selectedPlayer?player(selectedPlayer).name+' selected — tap a shirt or bench place to swap.':selectedSlot!==null?'Choose a player for the selected place.':'Tap a bench player, then a starting XI shirt to swap.';
 const cancel=root.querySelector('[data-action="cancel-selection"]');if(cancel)cancel.hidden=!selectedPlayer&&selectedSlot===null;
}
function blockingDecision(){
 const due=x=>career.ui.calendarStopAll||!x.deadline||x.deadline<=addDays(career.date,2);
 return (career.offers||[]).some(x=>['new','counter'].includes(x.status))||(career.clubLife?.stories||[]).some(x=>x.status==='pending'&&due(x))||(career.clubLife?.bookings||[]).some(x=>x.status==='offered'&&due(x));
}
async function advanceToDate(target){
 if(calendarAdvancing)return;if(match){toast('Finish the current match or report before advancing.');return;}if(!target||!/^\d{4}-\d{2}-\d{2}$/.test(target)||!Number.isFinite(Date.parse(target))||target<career.date){toast('Choose today or a future date.');return;}
 calendarAdvancing=true;drawFlowOpen=true;career.ui.calendarJourney={target,reason:'Advancing',paused:false};
 let reason='',steps=0;
 const destination={section:'calendar',sub:'lineup'};
 try{
  while(calendarAdvancing&&career.date<target&&steps<370){
   if(career.matchday||pendingDraw(career)||career.date===nextFixture()?.date){reason='A matchday or cup draw needs your attention.';break;}
   if(firstWeekEventPending()){reason='Club event ready.';break;}if(pendingBoardReview(career)){boardReviewOpen=pendingBoardReview(career).id;reason='Board review ready.';break;}if(blockingDecision()){reason='A decision needs your attention in Inbox.';break;}
   const before=career.date;calendarBatch=true;
   try{advance();}finally{calendarBatch=false;}
   steps++;
   if(career.date===before){reason='Review the current event before advancing.';break;}
   if(career.matchday||pendingDraw(career)||career.date===nextFixture()?.date){reason='Stopped for a matchday or cup draw.';break;}
   if(firstWeekEventPending()){reason='Club event ready.';break;}if(pendingBoardReview(career)){boardReviewOpen=pendingBoardReview(career).id;reason='Board review ready.';break;}if(blockingDecision()){reason='Stopped for a new decision in Inbox.';break;}
   if(steps%3===0){section=destination.section;sub=destination.sub;calendarDay=career.date;calendarMonth=career.date.slice(0,7);render();await new Promise(resolve=>setTimeout(resolve,0));}
  }
 }finally{
  calendarBatch=false;if(!calendarAdvancing&&!reason&&career.date<target)reason='Paused by you.';calendarAdvancing=false;career.ui.calendarJourney=career.date>=target?null:{target,reason:reason||'Paused before the selected date.',paused:true};section=destination.section;sub=destination.sub;calendarDay=career.date;calendarMonth=career.date.slice(0,7);careerPanelOpen=true;save();render();
 }
 toast(reason||('Reached '+fmtDate(career.date)+'.'));
}

root.addEventListener('keydown',()=>{touchActionReplay=null;},true);
