function calendarJourneyCard(compact=false){
 if(isStreamlined()){const j=career.ui.calendarJourney;if(!j?.paused||j.target<=career.date)return '';return `<section class="calendar-journey"><b>Saved destination · ${fmtDate(j.target)}</b><p>Continue stops for earlier matches or decisions.</p><div class="journey-actions"><button class="btn slim primary" data-action="calendar-resume">Continue towards this date</button><button class="btn slim ghost" data-action="calendar-clear-target">Clear destination</button></div></section>`;}
 const j=career.ui.calendarJourney;if(!j?.paused||j.target<=career.date)return '';
 const blocked=!!(match||career.matchday||pendingDraw(career)||career.date===nextFixture()?.date||blockingDecision());
 return `<section class="calendar-journey ${compact?'compact':''}" aria-label="Saved calendar destination"><b>Advancing to ${fmtDate(j.target)}</b><p>${html(blocked?match?'Finish the current match and report.':career.matchday?'Review the current matchday.':pendingDraw(career)?cupName(pendingDraw(career).competition)+' draw is ready.':career.date===nextFixture()?.date?'Your next match is today. Review preparation.':'A transfer or club decision needs attention in Inbox.':j.reason==='Paused by you.'?'Paused by you. Continue when ready.':'The previous stop has been resolved. Continue when ready.')}</p><div class="journey-actions">${blocked?'<button class="btn slim" data-action="calendar-review-stop">Review stop →</button>':`<button class="btn slim primary" data-action="calendar-resume">Continue to ${fmtDate(j.target)}</button>`}<button class="btn slim ghost" data-action="calendar-clear-target">Clear destination</button></div></section>`;
}
function outcomePanel(){if(!outcomeCard)return '';return `<div class="overlay outcome-overlay" role="dialog" aria-modal="true" aria-labelledby="outcome-title"><article class="modal outcome-modal"><h2 id="outcome-title">${html(outcomeCard.title)}</h2>${outcomeCard.rows.map(([label,value])=>`<div class="detail-row"><span>${html(label)}</span><b>${html(String(value))}</b></div>`).join('')}<p>${html(outcomeCard.note||'')}</p><button class="btn primary" data-action="outcome-close">Back to club</button></article></div>`;}
function matchQuickSummary(r){
 const incidents=(r.events||[]).filter(e=>['red','injury'].includes(e.type));
 const unavailable=(r.performances||[]).filter(x=>playerState(x.id).injuryDays>0||playerState(x.id).suspensionMatches>0);const next=nextFixture();
 return `<section class="match-quick-summary">${unavailable.length?`<p class="match-consequence"><b>Check selection:</b> ${unavailable.map(x=>html(player(x.id)?.name)+' · '+html(clubAvailability(x.id))).join('; ')}.</p>`:''}${next?`<p><b>Next:</b> ${html(clubName(opposition(next,career.clubId)))} · ${fmtDate(next.date)} · ${next.home===career.clubId?'Home':'Away'}</p>`:''}<div class="detail-row"><span>${r.home?'Net match income':'Away match income'}</span><b>${fmtMoney(r.income||0)}</b></div>${r.home?`<div class="detail-row"><span>Attendance</span><b>${(r.attendance||0).toLocaleString('en-GB')}</b></div>`:''}${incidents.map(e=>`<p class="match-consequence">${html(e.text)}</p>`).join('')||'<p>No injuries or red cards reported during the match.</p>'}</section>`;
}

function substitutionPicker(){
 const index=match.pendingSubIndex,hasIndex=Number.isInteger(index)&&index>=0&&index<11,incoming=match.bench.includes(selectedPlayer)?player(selectedPlayer):null,outgoing=hasIndex?player(match.lineup[index]):null,remaining=SUBSTITUTION_LIMIT-match.subCount;
 const ready=remaining>0&&incoming&&eligible(incoming.id)&&hasIndex&&canFillMatchSlot(index);
 return `<section class="substitution-picker" aria-label="Substitution picker"><h3>Your XI · ${remaining} substitutions left</h3><p class="compact-note">Tap the player coming off and a substitute, in either order. You can also drag a substitute onto a player.</p><div class="sub-xi">${subPitchRows()}</div><h4>Substitutes</h4><div class="sub-bench">${match.bench.filter(Boolean).map(id=>subPlayerCard(id,null)).join('')}</div><div class="sub-confirm"><p role="status">${remaining===0?'All three substitutions used.':incoming&&hasIndex?html(outgoing?.name||'Vacant place')+' off → '+html(incoming.name)+' on.':'Select both players to confirm a change.'}</p><div class="journey-actions"><button class="btn primary" data-action="confirm-substitution" ${ready?'':'disabled'}>Confirm substitution</button><button class="btn" data-action="cancel-substitution">Cancel</button><button class="btn" data-action="subs-done">Done & resume</button></div></div></section>`;
}
function matchReadinessBrief(){
 const opponent=opposition(match,career.clubId),plan=matchPlan(clubStyle(opponent),clubShape(opponent)),tired=career.lineup.filter(Boolean).filter(id=>playerFitness(id)<80),issues=lineupIssues();
 return `<section class="match-readiness-brief"><h3>Before kick-off</h3><p><b>Opponent:</b> ${html(clubShape(opponent))} · ${html(clubStyle(opponent))}. ${html(plan.reason)}</p><p><b>Your team:</b> ${issues.length?html(issues.join(' · ')): 'XI and bench eligible.'}${tired.length?' '+tired.length+' starter'+(tired.length===1?'':'s')+' below 80% condition.':''}</p><p class="compact-note">Suggested plan: ${html(plan.formation)} · ${html(plan.style)} · ${html(plan.order)}. Review advice before applying changes.</p></section>`;
}

// Streamlined management shares the season, finance and match engines.
function managementModeView(){return `<div class="app-shell mode-screen"><header class="topbar">${logo(true)}<button class="btn ghost" data-action="back-title">← Main menu</button></header><main class="mode-options glass"><span class="eyebrow">New career</span><h1>How do you want to manage?</h1><p>The same full season, clubs and competitions. Choose how much you handle.</p><button class="mode-card" data-action="choose-management-mode" data-mode="streamlined"><b>Streamlined</b><span>Pick your team, play matches and make the decisions that matter.</span><small>Three main screens · Continue to the next event · Assistant handles routine management</small></button><button class="mode-card" data-action="choose-management-mode" data-mode="in-depth"><b>In-depth</b><span>Take control of the full club experience.</span><small>All management screens · Daily/calendar advancing · Detailed budgets, training and club events</small></button><p class="compact-note">Management depth changes the interface and assistant responsibilities. Match rules and season length stay the same.</p></main></div>`;}
function streamState(){career.ui??={};return career.ui.streamline??={decisions:[],seen:[],newsCursor:career.news.length,summaryCursor:career.news.length,summary:[],searchPosition:'priority'};}
function initialiseStreamlined(newSeason=false){
 const prior=career.ui.streamline;career.ui.streamline={decisions:[],seen:[],newsCursor:career.news.length,summaryCursor:career.news.length,summary:[],searchPosition:'priority',priorTrainingAssistant:prior?.priorTrainingAssistant??!!career.training.assistant};career.training.assistant=true;career.ui.ownerWelcome.open=true;career.ui.ownerWelcome.returnTo=false;streamDecisionOpen=null;streamBudgetOpen=false;
 // Optional friendlies are omitted; already accepted fixtures remain part of the schedule.
 for(const f of career.friendlyInvitations||[])if(f.status==='offered')f.status='declined';
}
function switchManagementMode(mode){if(match||calendarAdvancing){toast('Finish the match or advancing first.');return;}if(!['streamlined','in-depth'].includes(mode)||mode===career.managementMode)return;
 if(mode==='streamlined'){career.managementMode=mode;initialiseStreamlined();}
 else{career.training.assistant=streamState().priorTrainingAssistant??false;career.managementMode=mode;streamDecisionOpen=null;streamBudgetOpen=false;career.ui.ownerWelcome.open=false;}
 careerPanelOpen=false;section='hub';sub='lineup';save();render();toast(mode==='streamlined'?'Streamlined management enabled.':'In-depth management enabled.');
}
function managementModeSetting(){return `<section class="management-mode-setting"><h3>Management depth</h3><select class="select" data-management-mode aria-label="Management depth"><option value="streamlined" ${isStreamlined()?'selected':''}>Streamlined</option><option value="in-depth" ${!isStreamlined()?'selected':''}>In-depth</option></select><p class="compact-note">Streamlined delegates training and routine renewals (up to a 10% wage increase, with four payrolls in reserve), omits unaccepted friendlies and club event proposals, and brings larger decisions to you. Transfers and upgrades always need your approval. Switching retains your season and players.</p></section>`;}
function streamDecisionValid(d){if(d.status!=='pending')return false;if(d.kind==='loan-enquiry')return owner(d.playerId)===career.clubId&&!career.loans[d.playerId];if(d.kind==='offer')return career.offers.some(o=>o.id===d.playerId&&o.clubId===d.clubId&&o.fee===d.fee&&['new','counter'].includes(o.status));if(d.kind==='contract')return owner(d.playerId)===career.clubId&&contractStatus(career,player(d.playerId)).days<=30;if(d.kind==='youth')return career.prospects.some(p=>p.id===d.playerId&&!p.promoted);if(d.kind==='injury')return owner(d.playerId)===career.clubId&&(playerState(d.playerId).injuryDays>0||playerState(d.playerId).suspensionMatches>0);return true;}
function streamPending(includeDeferred=false){return (career.ui.streamline?.decisions||[]).filter(d=>streamDecisionValid(d)&&(includeDeferred||!d.afterMatch||career.reports.length>=d.afterMatch)).sort((a,b)=>Number(b.urgent)-Number(a.urgent)||a.date.localeCompare(b.date));}
function streamEnqueue(kind,key,title,data={}){const st=streamState();if(st.seen.includes(key))return;st.seen.push(key);st.decisions.push({kind,key,title,date:career.date,status:'pending',...data});st.decisions=st.decisions.filter(d=>d.status==='pending').slice(-120);}
function streamAssistantRoutines(){
 career.training.assistant=true;const pool=squadPlayers(career.clubId),stars=new Set(pool.slice().sort((a,b)=>b.overall-a.overall).slice(0,3).map(p=>p.id));
 for(const p of pool){if(contractStatus(career,p).days>30)continue;const demand=renewalDemand(career,p,2),weekly=pool.reduce((n,x)=>n+x.wage,0);if(!stars.has(p.id)&&demand<=p.wage*1.10&&career.balance>=4*(weekly-p.wage+demand)){renewContract(career,source,p.id,demand,2);}else streamEnqueue('contract',`contract:${p.id}:${contractEnd(career,p)}`,'Contract decision',{playerId:p.id,urgent:contractStatus(career,p).days<=14});}
}
function streamCollectDecisions(){
 collectStadiumReviews();
 const st=streamState();
 for(const o of career.offers||[])if(['new','counter'].includes(o.status))streamEnqueue('offer',`offer:${o.id}:${o.clubId}:${o.fee}:${o.status}`,o.incoming?'Signing decision':'Transfer offer',{playerId:o.id,clubId:o.clubId,fee:o.fee,incoming:!!o.incoming,urgent:true});
 for(let i=st.newsCursor;i<career.news.length;i++){const n=career.news[i];if(['injury','suspension'].includes(n.kind)&&n.clubId===career.clubId&&career.reports.at(-1)?.date!==n.date)streamEnqueue('injury','availability:'+i,'Squad availability changed',{playerId:n.playerId,text:n.text,urgent:career.lineup.includes(n.playerId)});}
 st.newsCursor=career.news.length;
 if(career.balance<0)streamEnqueue('finance','finance:'+career.date.slice(0,7),'Club balance needs attention',{urgent:true});
 const month=career.date.slice(0,7),pool=squadPlayers(career.clubId),cover=squadCover(career,pool,slotsFor(career.formation));
 if(cover.rows.some(r=>r.status!=='covered')&&(cover.rows.some(r=>r.status==='short')||career.reports.length>=2)&&st.recruitmentCheckMonth!==month&&!st.seen.includes('recruit:'+month)){
  st.recruitmentCheckMonth=month;
  const rec=recruitmentRecommendations(career,source.players,slotsFor(career.formation),scoutKey(career.clubId));const rows=rec.rows.filter(x=>x.assessment.row?.status!=='covered').slice(0,3);if(rows.length)streamEnqueue('recruitment','recruit:'+month,'Suggested signings',{ids:rows.map(x=>x.p.id),roles:rows.map(x=>x.assessment.role)});
 }
 if(career.reports.length>=3){
  const weekly=pool.reduce((n,p)=>n+p.wage,0),affordable=['training','youth'].filter(kind=>{const q=investmentStatus(career,source,kind);return !q.complete&&career.balance-q.cost>=weekly*4;});
  if(affordable.length)streamEnqueue('investment','investment:'+month,'A chance to improve the club',{kinds:affordable});
  const prospect=(career.prospects||[]).filter(p=>!p.promoted&&!p.calledUp&&estimatedStars(p.potential)>=4).sort((a,b)=>b.potential-a.potential)[0];if(prospect)streamEnqueue('youth',`youth:${career.season}:${prospect.id}`,'A promising youngster',{playerId:prospect.id});
  const sale=pool.filter(p=>career.transferList.includes(p.id)||playerState(p.id).request).sort((a,b)=>b.wage-a.wage)[0];if(sale)streamEnqueue('sale',`sale:${career.season}:${sale.id}`,'Suggested sale',{playerId:sale.id});
 }
}
function streamProcessDraws(){let e,count=0;while((e=pendingDraw(career))&&count++<30){const r=e.round;if(r.entrants.includes(career.clubId)&&!career.ui.skipDrawPrompts?.[e.competition]){drawFlowOpen=true;return true;}r.revealed=[CL_ID,UC_ID].includes(e.competition)?r.selections.length:r.ties.length;r.eventSeen=true;if(r.entrants.includes(career.clubId)){const tie=r.ties?.find(t=>[t.home,t.away].includes(career.clubId)),group=r.groups?.find(g=>g.clubs.includes(career.clubId));streamEnqueue('draw',`draw:${career.season}:${e.competition}:${r.index}`,cupName(e.competition)+' · '+r.name,{text:tie?`You face ${clubName(tie.home===career.clubId?tie.away:tie.home)}.`:group?`Group ${group.name}: ${group.clubs.filter(id=>id!==career.clubId).map(clubName).join(', ')}.`:'Your club have a bye.'});}}return false;}
function streamSetSummary(){const st=streamState(),items=career.news.slice(st.summaryCursor).filter(n=>isClubNews(n)||['wages','commercial','contract-renewal','training','development','youth'].includes(n.kind));st.summary=items.slice(-12).map(n=>({date:n.date,text:n.text}));st.summaryCursor=career.news.length;}
async function streamlinedContinue(target=null){
 if(calendarAdvancing)return;if(match){if(match.phase==='report')closeMatchReport();else render();return;}if(outcomeCard){render();return;}if(career.ui.ownerWelcome.open){career.ui.ownerWelcome.open=false;}
 if(target&&(!/^\d{4}-\d{2}-\d{2}$/.test(target)||!Number.isFinite(Date.parse(target))||target<career.date)){toast('Choose today or a future date.');return;}
 calendarAdvancing=true;drawFlowOpen=false;career.ui.calendarJourney=target?{target,reason:'Continuing',paused:false}:null;render();let steps=0;
 try{while(calendarAdvancing&&steps++<800){
  if(firstWeekEventPending())break;if(pendingBoardReview(career)){boardReviewOpen=pendingBoardReview(career).id;break;}streamAssistantRoutines();if(streamProcessDraws())break;streamCollectDecisions();const decision=streamPending()[0];if(decision){streamDecisionOpen=decision.key;break;}
  if(career.matchday){const ours=dayFixtures(career).find(f=>[f.home,f.away].includes(career.clubId)&&f.homeGoals===null);if(ours){calendarBatch=true;try{continueMatchday();}finally{calendarBatch=false;}if(match)break;}else{settleOtherFixtures(true);career.matchdaySeen=[...new Set([...(career.matchdaySeen||[]),career.date])];career.matchday=null;postMatchTable=false;}continue;}
  if(career.date===nextFixture()?.date){calendarBatch=true;try{startScheduledMatch(nextFixture());}finally{calendarBatch=false;}break;}
  if(!nextFixture()&&seasonReady(career)){careerPanelOpen=true;section='hub';sub='lineup';break;}
  if(target&&career.date>=target)break;
  const date=career.date;calendarBatch=true;try{advance();}finally{calendarBatch=false;}if(match)break;if(career.date===date&&!career.matchday&&!pendingDraw(career)){toast('Review the current event before continuing.');break;}
  if(steps%3===0){await new Promise(resolve=>setTimeout(resolve,0));}
 }}finally{calendarBatch=false;calendarAdvancing=false;streamSetSummary();if(target&&career.date<target)career.ui.calendarJourney={target,reason:'Stopped for an event.',paused:true};else career.ui.calendarJourney=null;if(!match&&!careerPanelOpen){section='hub';sub='lineup';}save();render();}
}
function streamApproach(){return career.order==='Attack'?'Attacking':career.order==='Protect lead'?'Defensive':'Balanced';}
function setStreamApproach(value){if(!['Attacking','Balanced','Defensive'].includes(value))return;career.style=value==='Defensive'?'Counter':value==='Attacking'?'High press':'Balanced';career.order=value==='Defensive'?'Protect lead':value==='Attacking'?'Attack':'Standard';}
function streamlinedTeamControls(inModal=false){return `<section class="stream-team-controls"><label>Formation<select class="select" ${match?.phase==='live'?'data-match-setting="formation"':'data-squad-formation'}>${Object.keys(FORMATIONS).map(f=>`<option ${f===career.formation?'selected':''}>${f}</option>`).join('')}</select></label><label>Approach<select class="select" data-stream-approach>${['Attacking','Balanced','Defensive'].map(x=>`<option ${streamApproach()===x?'selected':''}>${x}</option>`).join('')}</select></label><div class="journey-actions">${match?.phase==='live'?'':'<button class="btn slim" data-action="auto-lineup">Assistant pick XI & bench</button>'}${!inModal?'<button class="btn slim" data-action="stream-find-player">Players and Transfers →</button>':''}</div></section>`;}
function streamlinedNav(){const pending=[...streamPending(true),...(pendingBoardReview(career)?[{urgent:pendingBoardReview(career).urgent}]:[])],current=!careerPanelOpen?'stadium':section==='squad'?'team':section==='organiser'||section==='calendar'?'competitions':'stadium';return `<nav class="bottom-nav mobile-navigation streamlined-navigation" aria-label="Club navigation"><button class="bottom-advance" data-action="advance" ${calendarAdvancing?'disabled':''}>${advanceLabel()} ↗</button><div class="main-destinations">${[['stadium','Club'],['team','Team'],['competitions','Season']].map(([id,label])=>`<button class="${current===id?'active':''} ${id==='stadium'&&pending.length?(pending.some(d=>d.urgent)?'needs-urgent':'needs-review'):id==='team'&&!validLineup()?'needs-urgent':''}" data-action="destination" data-destination="${id}">${label}${id==='stadium'?attentionBadge(pending):id==='team'&&!validLineup()?attentionBadge([{urgent:true}]):''}</button>`).join('')}</div></nav>`;}
function streamlinedStadiumCard(){const next=nextFixture(),pending=streamPending(true),latest=career.reports.at(-1);return `<aside class="stadium-manager-card stream-club-card" aria-label="Club overview">${boardShortcut()}<small>Streamlined · ${ownDivisionName()} · #${standings().findIndex(t=>t.id===career.clubId)+1}</small><button class="next-fixture-card" data-action="opponent"><small>${next?'Next match':'Season complete'}</small><b>${next?html(clubName(opposition(next,career.clubId))):'Review your season'}</b><span>${next?fmtDate(next.date)+' · '+(next.home===career.clubId?'Home':'Away')+' · '+(next.kickoff||'15:00'):''}</span></button><div class="journey-actions"><button class="btn slim" data-action="destination" data-destination="team">Prepare team →</button>${pending.length?`<button class="btn slim ${pending.some(d=>d.urgent)?'needs-urgent':''}" data-action="stream-pending">Pending decisions · ${pending.length}</button>`:''}</div>${latest?`<button class="btn slim ghost" data-action="news-report" data-date="${latest.date}">Last match: ${latest.us}–${latest.them} · ${html(clubName(latest.opponent))}</button>`:''}${streamState().summary.length?'<button class="btn slim ghost" data-action="stream-summary">Since your last stop →</button>':''}${!next&&seasonReady(career)?'<button class="btn primary" data-action="season-summary">Review season →</button>':''}</aside>`;}
function streamlinedWorkspace(){workspaceTabs='';let content='',label='Club';if(section==='settings'){label='Options & Help';content=managementModeSetting()+drawPreferences()+audioControls()+backupControls()+'<button class="btn slim" data-action="owner-welcome">Season briefing →</button>'+streamlinedHelp();}
 else if(section==='squad'){label=sub==='stream-market'?'Players and Transfers':'Team';content=sub==='stream-market'?streamlinedMarket():lineupEditor();}
 else if(section==='organiser'){label='Season';content=organiserSection();}
 else if(section==='calendar'){label='Calendar';content=calendarJourneyCard()+calendarView();}
 else if(section==='facilities'){label='Stadium upgrade';content=facilitiesSection();}
 else{const pending=streamPending(true);content=`${boardHub()}<button class="btn slim" data-action="stadium-planning">Stadium planning →</button><h3>Pending decisions</h3>${pending.map(d=>`<button class="route-card ${d.urgent?'needs-urgent':''}" data-action="stream-open-decision" data-key="${html(d.key)}"><b>${html(d.title)}</b><span>${fmtDate(d.date)} →</span></button>`).join('')||'<p>No decisions waiting.</p>'}<details class="stream-summary" open><summary>Since your last stop</summary>${streamState().summary.map(n=>`<p><small>${fmtDate(n.date)}</small><br>${html(n.text)}</p>`).join('')||'<p>No new updates.</p>'}</details>${!nextFixture()&&seasonReady(career)?'<button class="btn primary" data-action="season-summary">Review season</button>':''}`;}
 return `<div class="workspace-head"><strong>${label}</strong>${section==='organiser'?workspaceTabs:''}<button class="workspace-close" data-action="close-workspace" aria-label="Return to club">×</button></div><div class="workspace-body" data-rotation-scroll="workspace-${section}-${sub}">${content}</div>`;
}
function streamlinedMarket(){return `<button class="btn slim" data-action="destination" data-destination="team">← Team</button><h3>Players and Transfers</h3><details class="stream-market-suggestions"><summary>Assistant suggestions</summary>${recruitmentPanel(true)}</details>${transferSearchPanel()}${loanManagementPanel()}`;}

function streamlinedWelcome(){if(!career.ui.ownerWelcome?.open||match)return '';return `<div class="overlay owner-welcome-overlay" role="dialog" aria-modal="true" aria-label="Season briefing"><article class="modal"><span class="eyebrow">Streamlined management</span><h2>Your season at ${html(clubName(career.clubId))}</h2>${competitionSummary()}<p>Pick your team, choose an approach and press Continue. We’ll take you to your next match or a decision worth making.</p><p class="compact-note">Your assistant handles training, scouting reports and routine contract renewals within a 10% wage increase and four-payroll reserve. Bigger renewals, transfers and upgrades come to you. Optional friendlies and club event proposals are omitted.</p><button class="btn primary" data-action="close-owner-welcome">Let’s get started →</button></article></div>`;}
function streamlinedHelp(){return '<details class="getting-started"><summary>Streamlined guide</summary><p>Club shows your next fixture and pending decisions. Team lets you pick an XI, formation and Attacking, Balanced or Defensive approach. Season contains all fixtures, tables and cups.</p><p>Continue advances every intervening day, including payroll, recovery, training and other results. It stops for your matches and meaningful decision cards. Relevant draws offer a choice to watch selections or reveal the complete draw.</p><p>Close leaves a decision pending. Remind after next match defers it while Continue moves on. Optional suggestions can be dismissed. Transfers and spending require confirmation.</p><p>Routine contracts are renewed only within a 10% wage rise and a four-week payroll cash reserve. Larger renewals are decisions; leaving one on rolling terms retains the existing wage. Watching defaults to assistant substitutions; take control whenever you want.</p></details>';}
function streamlinedBudgetPanel(){if(!isStreamlined()||!streamBudgetOpen)return '';const weekly=weeklyWages();return `<div class="overlay stream-budget-overlay" role="dialog" aria-modal="true" aria-label="Club budget"><article class="modal"><h2>Club budget</h2><div class="detail-row"><span>Balance</span><b>${fmtMoney(career.balance)}</b></div><div class="detail-row"><span>Weekly wages</span><b>${fmtMoney(weekly)}</b></div><div class="detail-row"><span>Weekly commercial income</span><b>${fmtMoney(myClub().commercialWeekly||0)}</b></div><p>Wages and commercial income settle each Monday while Continue advances. Signing suggestions keep four payrolls in reserve.</p><button class="btn primary" data-action="stream-budget-close">Back to club</button></article></div>`;}
function streamlinedDecisionPanel(){if(!isStreamlined()||!streamDecisionOpen||match)return '';const d=streamPending(true).find(x=>x.key===streamDecisionOpen);if(!d)return '';const p=player(d.playerId);let body='',actions='';
 if(d.kind==='offer'){const a=d.incoming?null:saleAssessment(career,source.players,slotsFor(career.formation),p,d.fee);body=`<h3>${namedPlayer(p)}</h3><p>${d.incoming?'Selling club asks':'Offer from '+html(clubName(d.clubId))+':'} ${fmtMoney(d.fee)} · ${fmtMoney(p.wage)}/week</p>${a?`<p><b>Assistant:</b> ${html(a.verdict)}.</p><p>${html(a.reasons[0]||'')}</p>`:'<p>Review the squad and financial impact before signing.</p>'}`;actions='<button class="btn primary" data-action="stream-review-offer">Review transfer →</button><button class="btn" data-action="stream-decline-offer">Decline offer</button>';}
 else if(d.kind==='loan-enquiry'){body=`<p>${html(d.text)}</p><p>Review duration, wage share and recall terms before deciding. Playing time is an expectation, not a guarantee.</p>`;actions=`<button class="btn primary" data-action="review-loan-enquiry" data-player="${d.playerId}" data-key="${d.key}">Review loan</button><button class="btn" data-action="stream-dismiss">Keep at the club</button>`;}
 else if(d.kind==='injury'){body=`<p>${html(d.text)}</p><p>Review your XI and bench before the next match.</p>`;actions='<button class="btn primary" data-action="stream-review-team">Review team →</button>';}
 else if(d.kind==='draw'){body=`<p>${html(d.text)}</p><p>Fixtures and the full competition remain available under Season.</p>`;actions='<button class="btn primary" data-action="stream-dismiss">Got it</button>';}
 else if(d.kind==='recruitment'){body='<p>Your scouts have found affordable cover, possible upgrades or development options.</p>'+d.ids.map((id,i)=>{const x=player(id);return `<div class="stream-player-choice"><b>${html(x.name)} · ${d.roles[i]}</b><small>Age ${x.age} · ${scoutSigningProfile(x)}</small><span>${fmtMoney(estimatedBid(x,career))} estimated fee · ${fmtMoney(x.wage)}/week</span><button class="btn slim" data-action="stream-signing" data-id="${id}" data-role="${d.roles[i]}">Review signing →</button></div>`;}).join('');actions='<button class="btn" data-action="stream-dismiss">Keep the current squad</button>';}
 else if(d.kind==='contract'){const demand=renewalDemand(career,p,2),weekly=weeklyWages();body=`<h3>${namedPlayer(p)}</h3><p>Contract ends ${fmtDate(contractEnd(career,p))}.</p><div class="detail-row"><span>Weekly wage</span><b>${fmtMoney(p.wage)} → ${fmtMoney(demand)}</b></div><p>Two-year offer. No signing fee; the new wage starts with the next payroll.</p>${career.balance<4*(weekly-p.wage+demand)?'<p class="decision-alert">Your cash would cover fewer than four weekly payrolls.</p>':''}`;actions='<button class="btn primary" data-action="stream-renew-contract">Agree two-year renewal</button><button class="btn" data-action="stream-dismiss">Keep on current / rolling terms</button>';}
 else if(d.kind==='investment'){body='<p>You could invest while retaining four weekly payrolls in cash. Nothing is spent until you confirm.</p>'+d.kinds.map(kind=>{const q=investmentStatus(career,source,kind);return `<div class="stream-player-choice"><b>${q.title} · ${q.level} → ${q.target}★</b><span>${fmtMoney(q.cost)}</span><button class="btn slim" data-action="stream-investment" data-kind="${kind}">Review investment →</button></div>`;}).join('');actions='<button class="btn" data-action="stream-dismiss">Save the money</button>';}
 else if(d.kind==='stadium-review'){body=stadiumReviewStats();actions='<button class="btn primary" data-action="stream-stadium-review">Review upgrades</button>'+(d.stage==='mid'?'<button class="btn" data-action="stream-stadium-later">Remind me at season end</button>':'')+'<button class="btn" data-action="stream-dismiss">Keep the stadium as it is</button>';}
 else if(d.kind==='youth'){const prospect=career.prospects.find(p=>p.id===d.playerId);body=`<h3>${namedPlayer(prospect)}</h3><p>${prospect.primary} · Age ${prospect.age}</p><p>${youthReadinessText(prospect)}</p><p>Estimated potential ${estimatedStars(prospect.potential)}★</p><p>Call up temporarily, permanently promote, or keep him developing in the academy. A call-up adds his weekly wage while registered; permanent promotion retains senior terms.</p><p>Weekly wage: ${fmtMoney(prospect.wage)}</p>`;actions='<button class="btn" data-action="stream-call-up">Temporary call-up</button><button class="btn primary" data-action="stream-promote">Promote to squad</button><button class="btn" data-action="stream-dismiss">Keep developing</button>';}
 else if(d.kind==='sale'){body=`<h3>${namedPlayer(p)}</h3><p>${html(playerState(p.id).reason)} · ${fmtMoney(p.wage)}/week.</p><p>Estimated value ${fmtMoney(transferValue(p))}. Listing invites offers; it does not sell him automatically.</p>`;actions='<button class="btn primary" data-action="stream-list-sale">List for transfer</button><button class="btn" data-action="stream-dismiss">Keep him</button>';}
 else{body=`<p>Your club balance is ${fmtMoney(career.balance)}. Weekly wages are ${fmtMoney(weeklyWages())}.</p><p>Consider sales and avoid optional spending until the balance recovers.</p>`;actions='<button class="btn primary" data-action="stream-dismiss">Understood</button>';}
 return `<div class="overlay stream-decision-overlay" role="dialog" aria-modal="true" aria-label="Management decision"><article class="modal"><button class="panel-close" data-action="stream-decision-close" aria-label="Close; leave decision pending">×</button><span class="eyebrow">${d.urgent?'Important decision':'Club update'} · ${fmtDate(d.date)}</span><h2>${html(d.title)}</h2>${body}<div class="modal-actions">${actions}${d.kind!=='draw'?'<button class="btn ghost" data-action="stream-defer">Remind after next match</button>':''}</div></article></div>`;
}
function handleStreamlinedAction(el){const action=el.dataset.action;
 if(Date.now()<spotlightClickUntil&&el.closest('[data-spotlight]')){event.preventDefault();return;}if(action==='choose-management-mode'){setup.managementMode=el.dataset.mode==='streamlined'?'streamlined':'in-depth';view='setup';render();return true;}if(action==='pick-management-mode'){view='mode';render();return true;}if(!action.startsWith('stream-'))return false;if(calendarAdvancing)return true;
 if(!isStreamlined())return true;const d=streamPending(true).find(x=>x.key===streamDecisionOpen),done=()=>{if(d)d.status='done';streamDecisionOpen=null;};
 if(action==='stream-pending'||action==='stream-summary'){openRoute('hub',action==='stream-summary'?'summary':'pending');return true;}
 if(action==='stream-find-player'){openRoute('squad','stream-market');return true;}
 if(action==='stream-budget'){streamBudgetOpen=true;render();return true;}if(action==='stream-budget-close'){streamBudgetOpen=false;render();return true;}
 if(action==='stream-open-decision'){streamDecisionOpen=el.dataset.key;render();return true;}if(action==='stream-decision-close'){streamDecisionOpen=null;render();return true;}
 if(!d)return true;
 if(action==='stream-defer'){d.afterMatch=career.reports.length+1;streamDecisionOpen=null;}
 else if(action==='stream-dismiss')done();
 else if(action==='stream-review-team'){done();openRoute('squad','lineup');return true;}
 else if(action==='stream-review-offer'){transferReview=career.offers.find(o=>o.id===d.playerId&&o.clubId===d.clubId&&o.fee===d.fee);streamDecisionOpen=null;}
 else if(action==='stream-decline-offer'){const o=career.offers.find(o=>o.id===d.playerId&&o.clubId===d.clubId&&o.fee===d.fee);if(o)o.status='rejected';done();}
 else if(action==='stream-signing'){transferReview={id:el.dataset.id,clubId:owner(el.dataset.id),incoming:true,fee:estimatedBid(player(el.dataset.id)),role:el.dataset.role,bid:true};done();}
 else if(action==='stream-investment'){fundingReview=el.dataset.kind;done();}
 else if(action==='stream-stadium'){done();openRoute('facilities');return true;}
 else if(action==='stream-renew-contract'){const p=player(d.playerId),result=renewContract(career,source,p.id,renewalDemand(career,p,2),2);if(result.error){toast(result.error);return true;}done();outcomeCard={title:'Contract renewed',rows:[['Player',p.name],['Weekly wage',fmtMoney(result.wage)],['Contract ends',fmtDate(result.end)]],note:'The new wage applies to the next payroll.'};}
 else if(action==='stream-stadium-review'){done();openStadiumPlanning();return true;}
 else if(action==='stream-stadium-later'){done();toast('We’ll review the stadium again at season end.');}
 else if(action==='stream-call-up'){const error=callUpProspect(career,source,d.playerId);if(error){toast(error);return true;}done();toast('Called up; available in reserves.');}
 else if(action==='stream-promote'){const error=promoteProspect(career,source,d.playerId);if(error){toast(error);return true;}done();toast('Promoted to your squad.');}
 else if(action==='stream-list-sale'){career.transferList=[...new Set([...career.transferList,d.playerId])];done();toast('Listed for transfer. Offers still need your approval.');}
 save();render();return true;
}

function streamlinedPlayerPanel(){const p=player(instructionPlayer);if(!p||owner(p.id)!==career.clubId)return '';return `<article class="player-panel" role="dialog" aria-label="Player details"><button class="panel-close" data-action="close-player-panel" aria-label="Close player details">×</button><h3>${namedPlayer(p)}</h3>${attributePanel(p)}<p>${p.primary} · Age ${p.age} · ${p.overall} OVR · ${playerFitness(p.id)}% condition</p><p>${html(clubAvailability(p.id))} · ${fmtMoney(p.wage)}/week</p><p>${html(playerState(p.id).reason||'')}</p>${!match&&!p.academy?`<button class="btn slim" data-action="offer-loan" data-player="${p.id}">Review outgoing loan</button>`:''}</article>`;}

function confirmSelectedLineup(){if(!validLineup()){toast('Select eleven available starters, including a goalkeeper. Bench places may be left empty.');return}updateChecklist(career,managerItems());setChecklistChecked(career,'lineup',true);scoutedPlayer=null;opponentScoutExpanded=false;match.lineup=[...career.lineup];match.bench=[...career.bench];match.participants=Object.fromEntries(match.lineup.map(id=>[id,{start:0,end:null}]));match.phase='live';selectedPlayer=null;selectedSlot=null;match.pendingSubIndex=null;ensureMatchStats(match);match.speed=4;match.drawerOpen=false;match.startConditions=Object.fromEntries([...match.lineup,...match.oppLineup].filter(Boolean).map(id=>[id,playerFitness(id)]));career.time=match.kickoff||'15:00';match.events.push({minute:0,type:'info',text:'Kick-off! The match is underway.'});save();render()}

function streamlinedMatchChoice(){return `<span class="eyebrow">${match.kind==='cup'?cupStage(match):match.friendly?'Friendly':ownDivisionName()} · ${fmtDate(career.date)}</span><h2>${html(clubName(match.home))} v ${html(clubName(match.away))}</h2><p>${html(matchVenue().name)} · ${match.kickoff}</p>${matchReadinessBrief()}<details class="stream-match-team"><summary>Change XI & approach</summary>${lineupEditor(true)}</details><p class="compact-note">Your assistant handles routine match decisions. Open Team during the match to take control.</p><div class="modal-actions report-continue"><button class="btn primary" data-action="watch-match" ${!validLineup()?'disabled':''}>Watch match</button><button class="btn" data-action="simulate-match" ${!validLineup()?'disabled':''}>Simulate result</button><button class="btn ghost" data-action="close-choice">Back to club</button></div>`;}

// Mobile overview and squad helpers.
function reservePicker(pool){return `<label class="field reserve-picker">Choose a reserve<select class="select" data-reserve-picker aria-label="Choose a reserve player"><option value="">Select player, then tap an XI or bench place</option>${pool.map(p=>`<option value="${p.id}" ${selectedPlayer===p.id?'selected':''} ${!eligible(p.id)?'disabled':''}>${html(p.name)} · ${p.primary} · ${p.overall} OVR · ${playerFitness(p.id)}%${!eligible(p.id)?' · unavailable':''}</option>`).join('')}</select></label>`;}
function youthCallupPanel(short=false){const prospects=career.prospects.filter(p=>!p.promoted);return `<details class="youth-callups" ${short?'open':''}><summary>${short?'Need cover? Call up a youth player':'Youth squad · call-ups & returns'}</summary><p class="compact-note">Temporary call-ups occupy a registration place and add the displayed weekly wage while in the senior squad. Return them between matches. Permanent promotion retains senior terms and cannot be undone here.</p>${prospects.map(p=>`<div class="youth-callup-row"><span><b>${namedPlayer(p)}</b><small>${p.primary} · Age ${p.age} · ${youthReadinessText(p)} · ${estimatedStars(p.potential)}★ potential · ${fmtMoney(player(p.id)?.wage||p.wage)}/week${p.calledUp?' · Called up':''}</small></span><button class="btn slim" data-action="${p.calledUp?'return-youth':'call-up-youth'}" data-id="${p.id}">${p.calledUp?'Return to youth':'Call up'}</button><details><summary>Permanent promotion</summary><p class="compact-note">Keep this player permanently in the senior squad at ${fmtMoney(player(p.id)?.wage||p.wage)}/week. This removes the temporary return option.</p><button class="btn slim" data-action="permanent-youth" data-id="${p.id}">Confirm permanent promotion</button></details></div>`).join('')||'<p>No academy prospects available.</p>'}</details>`;}
function reportScoreEvents(r){const home=r.homeId||(r.home?career.clubId:r.opponent),away=r.awayId||(r.home?r.opponent:career.clubId);return `<div class="score-events" aria-label="Goals and sending offs">${[home,away].map(team=>{const events=(r.events||[]).filter(e=>e.team===team&&['goal','red'].includes(e.type));return `<div>${events.map(e=>`<p class="score-event ${e.type}"><span class="score-event-label">${e.type==='red'?'Sent off':'Goal'}</span> ${html(player(e.playerId)?.name||'Unknown player')} <b>${clockLabel(e.minute)}</b>${e.secondYellow?' (second yellow)':''}</p>`).join('')||'<p class="muted">No goals or sending offs</p>'}</div>`;}).join('')}</div>`;}
function liveActionFeed(){const events=match.events.slice(-2).reverse();return `<section class="live-action-feed" aria-label="Latest match action" data-live-action-count="${match.events.length}">${events.map(e=>`<p class="${e.type}"><b>${clockLabel(e.minute)}</b> ${html(e.text)}</p>`).join('')||'<p>Kick-off · Waiting for the first passage of play.</p>'}</section>`;}
function leagueForm(id){return career.schedule.flatMap(r=>r.fixtures.filter(f=>f.competition===divisionOf(career)&&f.kind!=='playoff'&&!f.friendly&&f.homeGoals!==null&&[f.home,f.away].includes(id)).map(f=>({...f,date:r.date}))).sort((a,b)=>a.date.localeCompare(b.date)).slice(-5).map(f=>{const us=f.home===id?f.homeGoals:f.awayGoals,them=f.home===id?f.awayGoals:f.homeGoals;return us>them?'W':us<them?'L':'D';});}
function miniatureLeague(){const table=standings(),own=table.findIndex(t=>t.id===career.clubId),start=Math.max(0,Math.min(own-2,table.length-5));return `<button class="mini-league" data-action="route" data-section="organiser" data-sub="table" aria-label="Open full league table"><b>${html(ownDivisionName())}</b><table><thead><tr><th>#</th><th>Club</th><th>Pts</th><th>GD</th><th>Form</th></tr></thead><tbody>${table.slice(start,start+5).map((t,i)=>{const form=leagueForm(t.id);return `<tr class="${t.id===career.clubId?'mine':''}" data-mini-club="${t.id}"><td>${start+i+1}</td><td class="mini-club-name" title="${html(clubName(t.id))}">${html(clubName(t.id))}</td><td>${t.Pts}</td><td>${t.GF-t.GA>0?'+':''}${t.GF-t.GA}</td><td class="form-dots" aria-label="Last five league games, oldest to newest: ${form.join(', ')||'none'}">${Array(5-form.length).fill('<i class="no-game" aria-label="No game"></i>').join('')}${form.map(f=>`<i class="form-${f}" title="${{W:'Win',D:'Draw',L:'Loss'}[f]}"></i>`).join('')}</td></tr>`;}).join('')}</tbody></table><small>Tap for full table · league form</small></button>`;}

function spotlightItems(){const items=[],pool=squadPlayers(career.clubId),pending=isStreamlined()?streamPending():[];
 const add=(title,text,action,attrs='',urgent=false)=>items.push({title,text,action,attrs,urgent});
 if(!validLineup())add('Team needs attention','Select eleven eligible starters, including a goalkeeper.','route','data-section="squad" data-sub="lineup"',true);
 const urgent=pending.find(d=>d.urgent);if(urgent)add('Decision needs attention',urgent.title,'stream-open-decision',`data-key="${html(urgent.key)}"`,true);
 if(career.balance<0)add('Balance needs attention','Review wages and spending before committing to transfers.',isStreamlined()?'stream-budget':'route',isStreamlined()?'':'data-section="finances" data-sub="lineup"',true);
 const players=pool.map(p=>({p,form:playerState(p.id).form.slice(-5)})).filter(x=>x.form.length).map(x=>({...x,average:x.form.reduce((a,b)=>a+b,0)/x.form.length})).sort((a,b)=>b.average-a.average);
 for(const x of players.slice(0,2))add('Player in form',`${x.p.name} · ${x.average.toFixed(1)} average over ${x.form.length} recent matches.`,'spotlight-player',`data-player="${x.p.id}"`);
 for(const [stat,label]of [['goals','Leading scorer'],['assists','Assist leader']]){const best=pool.filter(p=>(career.stats[p.id]?.[stat]||0)>0).sort((a,b)=>career.stats[b.id][stat]-career.stats[a.id][stat])[0];if(best)add(label,`${best.name} · ${career.stats[best.id][stat]} league ${stat}.`,'spotlight-player',`data-player="${best.id}"`);}
 const keeper=pool.filter(p=>p.primary==='GK'&&(career.stats[p.id]?.cleanSheets||0)>0).sort((a,b)=>career.stats[b.id].cleanSheets-career.stats[a.id].cleanSheets)[0];if(keeper)add('Safe hands',`${keeper.name} · ${career.stats[keeper.id].cleanSheets} league clean sheets.`,'spotlight-player',`data-player="${keeper.id}"`);
 const tired=career.lineup.map(player).filter(p=>p&&playerFitness(p.id)<80).sort((a,b)=>playerFitness(a.id)-playerFitness(b.id))[0];if(tired)add('Consider resting',`${tired.name} · ${playerFitness(tired.id)}% condition. Check your cover.`,'route','data-section="squad" data-sub="lineup"');
 const decision=pending.find(d=>!d.urgent);if(decision)add('Assistant recommendation',decision.title,'stream-open-decision',`data-key="${html(decision.key)}"`);
 const form=leagueForm(career.clubId);if(form.length){const wins=form.filter(x=>x==='W').length,streak=[...form].reverse().findIndex(x=>x==='L');add('Team form',`${wins} wins in your last ${form.length} league games${form.at(-1)!=='L'?' · unbeaten in '+(streak<0?form.length:streak):''}.`,'route','data-section="organiser" data-sub="table"');}
 if(!items.length)add('Ready for the season','Pick your XI and approach. Continue takes you to the next match or decision.','route','data-section="squad" data-sub="lineup"');return items;
}
function spotlightMarkup(){const items=spotlightItems(),pinned=items.find(x=>x.urgent),item=pinned||items[spotlightIndex%items.length];return `<div class="club-spotlight ${pinned?'needs-urgent':''}"><button class="spotlight-content" data-action="${item.action}" ${item.attrs}><small>Club spotlight${pinned?' · urgent':''}</small><b>${html(item.title)}</b><span>${html(item.text)}</span></button>${!pinned&&items.length>1?`<div class="spotlight-controls"><button data-action="spotlight-prev" aria-label="Previous spotlight">‹</button><span>${spotlightIndex%items.length+1} / ${items.length}</span><button data-action="spotlight-next" aria-label="Next spotlight">›</button><button data-action="spotlight-pause" aria-label="Pause or resume spotlight rotation">${career.ui.spotlightPaused?'▶':'Ⅱ'}</button></div>`:'<small class="spotlight-note">'+(pinned?'Tap to review':'Updates as your season progresses')+'</small>'}</div>`;}
function stadiumDashboard(){if(match||careerPanelOpen)return '';return `<div class="stadium-dashboard" aria-label="Club season overview"><div data-spotlight>${spotlightMarkup()}</div>${miniatureLeague()}</div>`;}
function syncSpotlight(){clearInterval(spotlightTimer);spotlightTimer=null;if(view!=='career'||match||careerPanelOpen||document.hidden||career.ui.spotlightPaused||matchMedia('(prefers-reduced-motion:reduce)').matches)return;spotlightTimer=setInterval(()=>{const target=root.querySelector('[data-spotlight]');if(!target||document.hidden||Date.now()<spotlightPauseUntil||document.activeElement?.closest?.('[data-spotlight]')||career.ui.spotlightPaused||spotlightItems().some(x=>x.urgent))return;spotlightIndex=(spotlightIndex+1)%spotlightItems().length;target.innerHTML=spotlightMarkup();},9000);spotlightTimer?.unref?.();}
function moveSpotlight(delta){spotlightPauseUntil=Date.now()+18000;const items=spotlightItems();spotlightIndex=(spotlightIndex+delta+items.length)%items.length;const target=root.querySelector('[data-spotlight]');if(target)target.innerHTML=spotlightMarkup();}
root.addEventListener('pointerdown',e=>{if(e.target.closest('[data-spotlight]')){spotlightPauseUntil=Date.now()+18000;spotlightSwipe={x:e.clientX,y:e.clientY};}},true);
root.addEventListener('pointerup',e=>{if(!spotlightSwipe)return;const start=spotlightSwipe;spotlightSwipe=null,spotlightClickUntil=0;if(e.target.closest('[data-spotlight]')&&Math.abs(e.clientX-start.x)>45&&Math.abs(e.clientY-start.y)<30){moveSpotlight(e.clientX<start.x?1:-1);spotlightPauseUntil=Date.now()+18000;spotlightClickUntil=Date.now()+500;}},true);
function stadiumReviewStats(){const home=career.reports.filter(r=>r.home&&!r.friendly),average=home.length?Math.round(home.reduce((n,r)=>n+r.attendance,0)/home.length):0,cap=usableCapacity(career,myClub()),sellouts=home.filter(r=>r.occupancy>=.95||r.attendance>=cap*.95).length;return `<div class="detail-row"><span>Average home attendance</span><b>${average.toLocaleString('en-GB')}</b></div><div class="detail-row"><span>Home games at least 95% full</span><b>${sellouts} / ${home.length}</b></div><div class="detail-row"><span>Current usable capacity</span><b>${cap.toLocaleString('en-GB')}</b></div><div class="detail-row"><span>Available cash</span><b>${fmtMoney(career.balance)}</b></div><p>${home.length&&average>=cap*.85?'Demand is strong. Consider extra capacity if the costs leave enough for wages.':'Consider improving existing stands or waiting until demand justifies expansion.'}</p>${constructionStatus()}<p class="compact-note">Opening the designer spends nothing. Before confirmation, each preview shows construction time, closed seats and home fixtures affected. Summer work can reduce disruption; larger projects may extend into next season.</p>`;}
function collectStadiumReviews(){if(!isStreamlined())return;const league=clubFixtures().filter(f=>f.competition===divisionOf(career)&&f.kind!=='playoff'&&!f.friendly),played=league.filter(f=>f.homeGoals!==null).length,ended=seasonReady(career),stage=ended?'end':played>=Math.ceil(league.length/2)?'mid':null;if(stage)streamEnqueue('stadium-review',`stadium:${career.season}:${stage}`,stage==='end'?'Summer stadium planning':'Mid-season stadium review',{stage});}
function openStadiumPlanning(){editing=normaliseLayout(career.stadium,myClub());selectedStand='N4';selectedStands=new Set([selectedStand]);openRoute('facilities','designer');}

function newsClubStrength(id){const ps=squadPlayers(id).slice().sort((a,b)=>b.overall-a.overall).slice(0,11);return ps.reduce((n,p)=>n+p.overall,0)/Math.max(1,ps.length);}
function drawInvitation(e){return `<div class="overlay draw-event-overlay"><article class="modal"><h2>${cupName(e.competition)} draw is ready</h2><p>${html(e.round.name)} · Your club are involved.</p><label><input type="checkbox" data-suppress-draw> Don't offer to watch this competition's draws again</label><p class="compact-note">You can restore these prompts in Options. Skipping still shows the outcome.</p><div class="modal-actions"><button class="btn primary" data-action="draw-watch-choice">Watch draw</button><button class="btn" data-action="draw-complete-choice">Show complete draw</button></div></article></div>`;}
function drawPreferences(){return `<details><summary>Optional draw prompts</summary><p>Continue offers draws involving your club. Suppressed competitions: ${Object.keys(career.ui.skipDrawPrompts||{}).filter(k=>career.ui.skipDrawPrompts[k]).map(cupName).join(', ')||'None'}.</p><button class="btn" data-action="restore-draw-prompts">Restore all draw prompts</button></details>`;}

function attributePanel(p){return `${nationalityDetail(p)}<section class="attribute-profile"><p class="muted">${owner(p.id)===career.clubId?'Ability / 100 · condition is shown separately':'Scout estimates / 100 · ranges narrow with better scouting'}</p>${attributeBars(p)}<button class="btn slim" data-action="compare-player" data-player="${p.id}">Compare player</button></section>`;}
function attributeBars(p,other=null){const compatible=!other||(p.primary==='GK')===(other.primary==='GK');if(!compatible)return '<p>Choose another goalkeeper for a like-for-like comparison.</p>';const range=(x,k)=>attributeEstimate(x,k,career.scoutingFunding||0,owner(x.id)===career.clubId);return `<div class="attribute-groups">${attributeGroups(p).map(([group,keys])=>`<section><h4>${group}</h4>${keys.map(k=>`<div class="attribute-row"><span>${k}</span>${[p,other].filter(Boolean).map((x,i)=>{const r=range(x,k);return `<div class="attribute-meter ${i?'comparison-second':''}" aria-label="${html(x.name)} ${k} ${r.low===r.high?r.low:r.low+' to '+r.high}"><i style="width:${r.centre}%"></i><b>${r.low===r.high?r.low:r.low+'–'+r.high}</b></div>`}).join('')}</div>`).join('')}</section>`).join('')}</div>`;}
function comparisonCandidates(){const p=player(comparisonPlayer);if(!p)return [];return source.players.filter(x=>x.id!==p.id&&!career.players[x.id]?.retired&&!career.players[x.id]?.unregistered&&(x.primary==='GK')===(p.primary==='GK')&&(comparisonScope!=='own'||owner(x.id)===career.clubId)&&(comparisonScope==='own'||((!comparisonFilters.league||divisionOf(career,owner(x.id))===comparisonFilters.league)&&(!comparisonFilters.club||owner(x.id)===comparisonFilters.club)&&(!comparisonFilters.nationality||x.nationality===comparisonFilters.nationality)&&(!comparisonFilters.position||x.primary===comparisonFilters.position)&&(!comparisonFilters.free||x.freeAgent)))&&normaliseName(x.name+' '+(playerAliases[x.id]||'')).includes(normaliseName(comparisonQuery))).sort((a,b)=>a.name.localeCompare(b.name));}
function comparisonResults(){const rows=comparisonCandidates();return `<label class="field">Choose player · ${rows.length} matches<select class="select" data-comparison-player><option value="">Select a player</option>${rows.map(x=>`<option value="${x.id}" ${x.id===comparisonOther?'selected':''}>${html(x.name)} · ${x.primary}${comparisonScope==='all'?' · '+html(clubName(owner(x.id))):''}</option>`).join('')}</select></label>`;}
function comparisonControls(){const filter=(key,label,rows)=>`<label>${label}<select class="select" data-comparison-filter="${key}"><option value="">Any</option>${rows.map(([id,name])=>`<option value="${id}" ${comparisonFilters[key]===id?'selected':''}>${html(name)}</option>`).join('')}</select></label>`;return `<div class="comparison-picker"><label class="field">Compare with<select class="select" data-comparison-scope><option value="own" ${comparisonScope==='own'?'selected':''}>Your squad</option><option value="all" ${comparisonScope==='all'?'selected':''}>All clubs & free agents</option></select></label><input class="input" type="search" data-comparison-search placeholder="Search name or historical counterpart" value="${html(comparisonQuery)}">${comparisonScope==='all'?`<details class="comparison-filters"><summary>Filters</summary><div class="designer-fields">${filter('league','League',[...DIVISIONS.map(d=>[d.id,d.name]),['european','European clubs']])}${filter('club','Club',source.clubs.filter(c=>!comparisonFilters.league||divisionOf(career,c.id)===comparisonFilters.league).map(c=>[c.id,clubName(c.id)]))}${filter('nationality','Nationality',Object.entries(COUNTRIES).map(([id,c])=>[id,c[0]]).sort((a,b)=>a[1].localeCompare(b[1])))}${filter('position','Position',['GK','LB','CB','RB','DM','CM','AM','LW','RW','ST'].map(x=>[x,x]))}${filter('free','Availability',[['yes','Free agents only']])}</div></details>`:''}<div data-comparison-results>${comparisonResults()}</div></div>`;}
function comparisonPanel(){const p=player(comparisonPlayer),other=player(comparisonOther);if(!p)return '';return `<div class="overlay comparison-overlay" role="dialog" aria-modal="true" aria-label="Player profile and comparison"><article class="modal"><button class="panel-close" data-action="comparison-close">×</button><h2>Player comparison</h2>${comparisonControls()}<div class="comparison-head">${[p,other].filter(Boolean).map((x,i)=>`<section class="${i?'comparison-second':''}"><b>${namedPlayer(x)}</b><small>${x.primary} · Age ${x.age} · ${scoutRating(x,owner(x.id))} OVR</small><small>${fmtMoney(x.wage)}/week · Est. fee ${fmtMoney(estimatedBid(x,career))}</small></section>`).join('')}</div>${attributeBars(p,other)}</article></div>`;}
function handlePlayerTools(el){const a=el.dataset.action;if(a==='first-week-ack'){if(career.clubLife?.firstWeekEvent)career.clubLife.firstWeekEvent.read=true;save();render();return true;}if(a==='compare-player'){comparisonPlayer=el.dataset.player;comparisonOther=null;comparisonQuery='';comparisonScope='own';
comparisonFilters={league:'',club:'',nationality:'',position:'',free:''};render();return true;}if(a==='comparison-select'){comparisonOther=el.dataset.player;render();return true;}if(a==='comparison-close'){comparisonPlayer=null;render();return true;}if(a==='agree-future-transfer'){const o=transferReview,p=player(el.dataset.id);if(!o||o.id!==p?.id||!o.incoming||p.freeAgent||career.loans[p.id]||contractStatus(career,p).days>366)return true;career.futureTransfers??=[];if(career.futureTransfers.some(x=>x.id===p.id&&x.status==='agreed'))return true;const stance=sellingPosition(p);if(stance.blocked){toast(stance.reason);return true;}if(o.bid&&!o.futureQuoted&&stance.multiplier>1){o.fee=Math.round(estimatedBid(p,career)*stance.multiplier/10000)*10000;o.futureQuoted=true;render();toast('Selling club terms updated. Review the fee before agreeing.');return true;}if(career.balance<o.fee){toast('Insufficient funds for the agreed fee.');return true;}const arrival=String(Number(career.seasonStart.slice(0,4))+1)+'-07-01';career.balance-=o.fee;career.futureTransfers.push({id:p.id,from:owner(p.id),to:career.clubId,fee:o.fee,wage:p.wage,arrival,status:'agreed'});career.news.push({date:career.date,kind:'transfer',important:true,text:`${p.name}: club-approved summer transfer agreed for ${fmtMoney(o.fee)}. Arrival ${fmtDate(arrival)}; wages begin on arrival.`});transferReview=null;save();render();return true;}return false;}
root.addEventListener('input',e=>{if(e.target.matches('[data-comparison-search]')){comparisonQuery=e.target.value;const list=root.querySelector('[data-comparison-results]');if(list)list.innerHTML=comparisonResults();}});
root.addEventListener('change',e=>{if(e.target.matches('[data-comparison-scope]')){comparisonScope=e.target.value;render();}});
function settleFutureTransfers(){for(const deal of career.futureTransfers||[]){if(deal.status!=='agreed'||deal.arrival>career.date)continue;const p=player(deal.id);if(!p||career.players[p.id]?.retired||owner(p.id)!==deal.from){deal.status='cancelled';career.balance+=deal.fee;career.news.push({date:career.date,important:true,text:'An agreed summer transfer could not complete. The fee has been refunded.'});continue;}const space=canRegister(career,source,p);deal.status='completed';career.owners[p.id]=deal.to;career.players[p.id].unregistered=!space;career.contracts[p.id]={end:String(Number(career.date.slice(0,4))+2)+'-06-30'};career.news.push({date:career.date,kind:'transfer',important:true,text:`${p.name} has arrived on his agreed ${fmtMoney(p.wage)}/week terms.${career.players[p.id].unregistered?' Registration is pending: free a squad place.':''}`});}}
function recruitmentBulletin(){const month=career.date.slice(0,7);if(!['07','08','12','01','03'].includes(career.date.slice(5,7))||career.recruitmentBulletinMonth===month)return;career.recruitmentBulletinMonth=month;const result=recruitmentRecommendations(career,source.players,slotsFor(career.formation),month),rows=result.rows.slice(0,3);if(!rows.length)return;career.news.push({date:career.date,kind:'scouting',action:'coverage',text:'Scouting shortlist: '+rows.map(x=>`${x.p.name} (${x.assessment.role}) — ${x.assessment.row?.status!=='covered'?'fills a squad need':x.p.age<=21?'development opportunity':'possible upgrade'}, ${fmtMoney(x.fee)} plus ${fmtMoney(x.p.wage)}/week`).join('; ')+'. Review Players and Transfers.'});if(isStreamlined())streamEnqueue('recruitment','scouting:'+month,'Scouting recommendations',{ids:rows.map(x=>x.p.id),roles:rows.map(x=>x.assessment.role)});}
function weeklyWages(){return Math.round(source.players.filter(p=>owner(p.id)===career.clubId&&!playerState(p.id).retired&&!playerState(p.id).academyOnly).reduce((n,p)=>n+p.wage,0)+loanWageAdjustment(career,source));}
function youthReadinessText(p){const r=youthReadiness(career,source,p);return `Current readiness ${r.low}–${r.high}/100 · ${r.label}`;}
function loanManagementPanel(){const held=source.players.filter(p=>owner(p.id)===career.clubId&&playerState(p.id).unregistered&&!playerState(p.id).retired&&!playerState(p.id).academyOnly),loans=Object.entries(career.loans||{}).filter(([,l])=>l.parent===career.clubId),candidates=loanCandidates(career,source).slice(0,4);return `<details class="loan-management"><summary>Loans & squad places · ${squadSpace(career,source).total}/30 active</summary><p>Academy players are separate. Outgoing loans free a place; returning players await registration if full. Contracted players still receive wages while awaiting registration.</p>${held.map(p=>`<p><b>${namedPlayer(p)}</b> · Awaiting registration <button class="btn slim" data-action="register-senior" data-id="${p.id}">Register</button></p>`).join('')}${loans.map(([id,l])=>`<article class="loan-card"><b>${html(player(id).name)} · ${html(clubName(l.to))}</b><p>Until ${l.end||l.season} · borrower pays ${l.contribution??100}% · ${l.role||'Squad role'}</p><p>${l.appearances||0} appearances · ${l.minutes||0} minutes · ${l.minutes?(l.ratingTotal/l.minutes).toFixed(1):'—'} rating</p>${l.recall?`<button class="btn slim" data-action="recall-loan" data-id="${id}" ${career.date<l.recallDate?'disabled':''}>Recall${career.date<l.recallDate?' from '+l.recallDate:''}</button>`:'<small>No early recall agreed.</small>'}</article>`).join('')}<h4>Assistant loan candidates</h4>${candidates.map(p=>`<p>${html(p.name)} · ${p.primary} · Age ${p.age} — ${p.age<=23?'senior experience could help development':'currently outside the starting XI'} <button class="btn slim" data-action="offer-loan" data-player="${p.id}">Review loan</button></p>`).join('')||'<p>No suitable candidates at present.</p>'}</details>`;}
function loanReviewPanel(){const p=player(loanReviewPlayer);if(!p)return '';const destinations=loanDestinations(career,source,p);return `<div class="overlay loan-review-overlay" role="dialog" aria-modal="true" aria-label="Loan agreement"><article class="modal"><button class="panel-close" data-action="close-loan-review">×</button><h2>Loan · ${namedPlayer(p)}</h2><p>${p.primary} · Age ${p.age} · ${fmtMoney(p.wage)}/week</p><label class="field">Interested club<select class="select" data-loan-club>${destinations.map(d=>`<option value="${d.club.id}">${html(clubName(d.club.id))} · ${d.role} · level ${d.strength}</option>`).join('')}</select></label><label class="field">Duration<select class="select" data-loan-months><option value="3">Three months</option><option value="6">Six months</option><option value="12">To season end (30 June)</option></select></label><label class="field">Borrower wage contribution<select class="select" data-loan-share>${[25,50,75,100].map(n=>`<option value="${n}" ${n===50?'selected':''}>${n}% · you retain ${fmtMoney(p.wage*(1-n/100))}/week</option>`).join('')}</select></label><label><input type="checkbox" data-loan-recall checked> Allow recall after 28 days</label><p>Playing time depends on selection, form and availability. Match minutes drive reports and development. Nothing changes until you confirm.</p><div class="modal-actions"><button class="btn primary" data-action="confirm-loan" data-id="${p.id}" ${!destinations.length?'disabled':''}>Confirm loan</button><button class="btn" data-action="close-loan-review">Cancel</button></div></article></div>`;}
function handleLoanTools(el){const a=el.dataset.action;if(a==='review-loan-enquiry'){const d=streamState().decisions.find(x=>x.key===el.dataset.key);if(d)d.status='done';streamDecisionOpen=null;loanReviewPlayer=el.dataset.player;render();return true;}if(a==='close-loan-review'){loanReviewPlayer=null;render();return true;}if(a==='confirm-loan'){if(match)return true;const error=acceptLoan(career,source,el.dataset.id,root.querySelector('[data-loan-club]')?.value,Number(root.querySelector('[data-loan-months]')?.value),Number(root.querySelector('[data-loan-share]')?.value),!!root.querySelector('[data-loan-recall]')?.checked);if(error){toast(error);return true;}loanReviewPlayer=null;instructionPlayer=null;const picks=bestLineup(career.clubId,career.formation);career.lineup=picks.lineup;career.bench=picks.bench;save();render();return true;}if(a==='recall-loan'){if(match)return true;const error=returnLoan(career,source,el.dataset.id,true);if(error)toast(error);else{save();render();}return true;}return false;}
function loanEnquiries(){const month=career.date.slice(0,7);if(career.loanEnquiryMonth===month)return;career.loanEnquiryMonth=month;const p=loanCandidates(career,source).find(x=>loanDestinations(career,source,x).length);if(!p||squadSpace(career,source).total<=18)return;const dest=loanDestinations(career,source,p)[0],text=`${clubName(dest.club.id)} have asked about a loan for ${p.name}. Your assistant sees a chance for ${p.age<=23?'development through senior matches':'regular match involvement'}. Review Loans & squad places.`;career.news.push({date:career.date,kind:'loan-enquiry',text});if(isStreamlined())streamEnqueue('loan-enquiry','loan:'+month,'Loan enquiry',{playerId:p.id,text});}
function revealDrawTeam(r){if(r.revealed>=r.ties.length)return;if(r.partialReveal){r.revealed++;r.partialReveal=false;}else r.partialReveal=true;}
function partialDrawTeam(r){const t=r.ties?.[r.revealed];return r.partialReveal&&t?`<p class="${t.home===career.clubId?'mine':''}">${html(clubName(t.home))} v <span class="muted">Next team…</span></p>`:'';}
function lateSeasonRivalResult(f){if(f.competition!==divisionOf(career)||career.date.slice(5,7)<'03'||career.date.slice(5,7)>'06')return false;const rows=standings(),at=rows.findIndex(t=>t.id===career.clubId),near=new Set(rows.slice(Math.max(0,at-2),at+3).map(t=>t.id));return near.has(f.home)||near.has(f.away);}

function namedPlayer(p,short=false){return `<span class="player-name-with-flag"><span>${html(short?shortPlayerName(p):p.name)}</span>${flagMarkup(p.nationality)}</span>`;}
function nationalityDetail(p){return `<p class="nationality-detail">Nationality: ${html(COUNTRIES[p.nationality]?.[0]||'Not yet verified')}</p>`;}
function runManagerDay(){initialiseManagers(career,source);managerDay(career,source);const a=assessSeason(career,ownLeague(),standings()),weekly=weeklyWages();a.forecast=career.balance-(weekly-(myClub().commercialWeekly||0))*4;const r=boardReviewDay(career,a,{weekly});if(r&&!match)boardReviewOpen=r.id;}
function boardShortcut(){const r=pendingBoardReview(career);return `<button class="btn slim ghost ${r?(r.urgent?'needs-urgent':'needs-review'):''}" data-action="board-review">${r?'Board report ready':'Manager & board'} →</button>`;}
function boardHub(){const r=pendingBoardReview(career);return `<section class="board-hub">${boardShortcut()}${r?`<p>${fmtDate(r.date)} · ${html(r.status)}</p>`:''}</section>`;}
function managerCard(id){const m=managerFor(career,id);if(!m)return '';const r=m.jobRecord,own=id===career.clubId;return `<details class="manager-profile"><summary>Manager · ${html(m.name)} ${flagMarkup(m.nationality)}</summary><p>${own?'Your managerial career':'Fictional manager'}${m.fictional?' · Age '+(Number(career.date.slice(0,4))-m.birthYear):''} · ${html(COUNTRIES[m.nationality]?.[0]||'Nationality not selected')}</p><p>In charge since ${fmtDate(m.joined)} · ${own?career.formation:m.formation} · ${html(own?career.style:m.style)}</p><p>Current spell: ${r.played} played · ${r.won}W ${r.drawn}D ${r.lost}L</p>${r.played?`<p>Win rate ${Math.round(r.won/r.played*100)}% · Goals ${r.gf}–${r.ga}</p>`:'<p>No recorded competitive matches in this spell.</p>'}<p>${own?'Board confidence: '+assessSeason(career,ownLeague(),standings()).boardBand.label:'Job status: '+(m.recent.length<8?'Still being assessed':m.confidence<30?'Under pressure':m.confidence<50?'Under scrutiny':'Secure')}</p>${own?`<label class="field">Your nationality<select class="select" data-manager-nationality><option value="">Choose nationality</option>${Object.entries(COUNTRIES).sort((a,b)=>a[1][0].localeCompare(b[1][0])).map(([key,c])=>`<option value="${key}" ${m.nationality===key?'selected':''}>${c[0]}</option>`).join('')}</select></label>`:''}${m.history.length?`<h4>Previous appointments</h4>${m.history.slice().reverse().map(h=>`<p>${html(clubName(h.clubId))} · ${fmtDate(h.from)}–${fmtDate(h.to)}<br>${html(h.reason)} · ${h.record.won}W ${h.record.drawn}D ${h.record.lost}L</p>`).join('')}`:''}${!own?'<small>Records cover matches simulated during this career.</small>':''}</details>`;}
function boardReportBody(r){return `<span class="eyebrow">${r.monthly?'Monthly':'Quarterly'} review · ${fmtDate(r.date)}</span><h2>Board confidence: ${html(r.status)}</h2><div class="board-confidence ${r.urgent?'board-concern':''}"><strong>${r.confidence}/100</strong><span>${r.urgent?'We will review progress monthly while concerns remain.':'Routine reviews every three months.'}</span></div><h3>What pleases us</h3><ul>${r.positives.map(t=>`<li>${html(t)}</li>`).join('')}</ul><h3>Where we want improvement</h3><ul>${r.improvements.map(t=>`<li>${html(t)}</li>`).join('')}</ul><h3>Priorities before the next review</h3><ul>${r.priorities.map(t=>`<li>${html(t)}</li>`).join('')}</ul><details><summary>Report figures</summary><p>League ${r.position} · Target top ${r.target}<br>${r.points} points from ${r.played} games<br>Balance ${fmtMoney(r.balance)} · Weekly wages ${fmtMoney(r.weekly)}</p></details>`;}
function boardReviewPanel(){if(!boardReviewOpen||match)return '';const reports=career.managerReviewState?.reports||[],r=reports.find(x=>x.id===boardReviewOpen);return `<div class="overlay board-review-overlay" role="dialog" aria-modal="true" aria-label="Manager and board"><article class="modal"><button class="panel-close" data-action="close-board-review" aria-label="Close board report">×</button>${r?boardReportBody(r):`<h2>Manager & board</h2>${managerCard(career.clubId)}<p>Routine reviews arrive at the end of every third month. Pressing concerns bring an additional month-end review.</p><p>Your board confidence is advisory in this release; your career will not be ended by a dismissal.</p>`}${r&&!r.read?`<button class="btn primary" data-action="acknowledge-board-review" data-id="${r.id}">Acknowledge report</button>`:''}<details class="board-report-archive"><summary>Report archive · ${reports.length}</summary>${reports.slice().reverse().map(x=>`<button class="btn slim ${!x.read?'needs-review':''}" data-action="board-review" data-id="${x.id}">${fmtDate(x.date)} · ${html(x.status)}${x.read?'':' · Unread'}</button>`).join('')||'<p>Your first report is still to come.</p>'}</details>${r?'<button class="btn slim ghost" data-action="manager-home">Your manager profile</button>':''}</article></div>`;}
function handleManagerTools(el){const a=el.dataset.action;if(a==='board-review'||a==='manager-home'){boardReviewOpen=a==='manager-home'?'home':el.dataset.id||pendingBoardReview(career)?.id||'home';render();return true;}if(a==='close-board-review'){boardReviewOpen=null;render();return true;}if(a==='acknowledge-board-review'){const r=career.managerReviewState.reports.find(x=>x.id===el.dataset.id);if(r)r.read=true;boardReviewOpen=null;save();render();return true;}return false;}
root.addEventListener('change',event=>{if(event.target.matches?.('[data-manager-nationality]')){const code=event.target.value;if(code&&!COUNTRIES[code])return;managerFor(career,career.clubId).nationality=code;save();render();const panel=root.querySelector('.board-review-overlay .manager-profile');if(panel)panel.open=true;}});

function firstWeekEventPending(){return career?.clubLife?.firstWeekEvent&&!career.clubLife.firstWeekEvent.read;}
function firstWeekEventPanel(){
 if(!firstWeekEventPending()||match)return '';
 const story=career.clubLife.stories.find(s=>s.id===career.clubLife.firstWeekEvent.id);
 if(!story)return '';
 return `<div class="overlay board-review-overlay" style="z-index:220" role="dialog" aria-modal="true" aria-label="Club event"><article class="modal"><span class="eyebrow">Life at the club · ${fmtDate(story.date)}</span><h2>${html(story.title)}</h2><p>${html(story.text)}</p><p>${html(story.result)}</p><button class="btn primary" data-action="first-week-ack">Back to the club →</button></article></div>`;
}

function stadiumBlueprint(){const areas=[['NW','NW corner'],['N','North stand'],['NE','NE corner'],['W','West stand'],['pitch','Pitch'],['E','East stand'],['SW','SW corner'],['S','South stand'],['SE','SE corner']];return `<div class="stadium-blueprint" aria-label="Stadium section selector">${areas.map(([id,label])=>{if(id==='pitch')return '<div class="blueprint-pitch" aria-hidden="true"><i></i></div>';const ids=SECTIONS.filter(x=>x.side===id).map(x=>x.id),on=ids.every(x=>selectedStands.has(x));return `<button class="${on?'selected':''}" data-action="blueprint-area" data-area="${id}" aria-pressed="${on}">${label}</button>`}).join('')}</div><button class="btn slim" data-action="blueprint-clear">Clear selection</button>`;}
root.addEventListener('change',event=>{const el=event.target;if(el.matches('[data-comparison-player]')){comparisonOther=el.value||null;render();}if(el.matches('[data-comparison-filter]')){comparisonFilters[el.dataset.comparisonFilter]=el.value;if(el.dataset.comparisonFilter==='league')comparisonFilters.club='';const out=root.querySelector('[data-comparison-results]');if(out)out.innerHTML=comparisonResults();if(el.dataset.comparisonFilter==='league'){render();root.querySelector('.comparison-filters')?.setAttribute('open','');}}});

function subPlayerCard(id,index){const p=player(id),bench=index===null,pos=bench?p?.primary:slotsFor(career.formation)[index],disabled=bench?match.subCount>=SUBSTITUTION_LIMIT||!eligible(id):!canFillMatchSlot(index),selected=bench?selectedPlayer===id:match.pendingSubIndex===index,incoming=player(selectedPlayer),suitable=bench?Number.isInteger(match.pendingSubIndex)&&suitsRole(p,slotsFor(career.formation)[match.pendingSubIndex]):incoming&&suitsRole(incoming,pos);return `<button class="sub-player ${selected?'selected':''} ${suitable?'suitable':''}" ${disabled?'disabled':''} data-action="${bench?'match-bench':'match-replace'}" aria-label="${html(p?.name||'Vacant')} · ${pos}" data-player="${id||''}" ${bench?`draggable="${!disabled}"`:`data-index="${index}" data-live-drop="${index}"`} style="--sub-row:${bench?1:pos==='GK'?4:['LB','CB','RB'].includes(pos)?3:pos==='ST'?1:2}">${shirt(p,true)}<span><b>${p?html(p.name.split(' ').at(-1)):'Vacant'}</b><small>${pos} · ${p?(bench?playerFitness(id):matchInsight(id,career.clubId,pos).condition)+'%':'—'}</small>${!bench&&p?`<small>Rating ${matchInsight(id,career.clubId,pos).rating??'—'}</small>`:''}</span></button>`;}

function sellingPosition(p){if(p.freeAgent)return {blocked:false,multiplier:1,reason:'Free agent: no transfer fee.'};const seller=owner(p.id),pool=squadPlayers(seller),listed=career.transferList.includes(p.id),days=contractStatus(career,p).days,key=pool.filter(x=>x.overall>p.overall).length<5,rivals=[['C01','C18'],['C11','C08'],['C12','C47'],['C14','C21'],['C16','C28'],['C24','C02'],['C15','C07'],['C32','C27'],['C17','C39'],['EU002','EU004'],['EU007','EU009']].some(pair=>pair.includes(seller)&&pair.includes(career.clubId));const same=divisionOf(career,seller)===divisionOf(career),table=same?standings(divisionOf(career)):[],a=table.findIndex(x=>x.id===seller),b=table.findIndex(x=>x.id===career.clubId),played=table[a]?.P||0,challenger=same&&played>=8&&a>=0&&b>=0&&Math.abs(a-b)<=3,pressure=listed||days<=183;
if(pool.length<=18)return {blocked:true,multiplier:1,reason:'The club needs to retain enough players for its matchday squad.'};
if(rivals&&key&&days>366&&!listed)return {blocked:true,multiplier:1,reason:'The club refuses to sell a key player on a long contract to a local rival.'};
const multiplier=pressure?1:rivals?1.3:challenger&&key?1.2:key&&days>366?1.1:1;return {blocked:false,multiplier,reason:pressure?(listed?'The player is listed: the club is willing to release funds from the squad.':'The contract is running down, making the club more open to a deal.'):rivals?'The club demands a 30% premium for strengthening a rival.':challenger&&key?'The club demands a 20% premium for strengthening a nearby league challenger.':multiplier>1?'A key player on a long contract: the club wants 10% above the estimate.':'The club is open to negotiation at the estimated fee.'};}
function sellingFeedback(p){const stance=sellingPosition(p);return `<p class="selling-feedback"><b>Selling club:</b> ${html(stance.reason)}</p>`;}

function historicalWinnersPanel(id){const key=id===CL_ID?'cl':id===UC_ID?'uc':id===FA_ID?'fa':id===CUP_ID?'lc':id,history=HISTORICAL_WINNERS[key]||[];let recent=[];if(['premier','first','second'].includes(key))recent=(career.divisionHistory||[]).map(h=>({year:1998+h.season,club:h.tables[key]?.[0]?.id}));else recent=(key==='cl'?career.clHistory:key==='uc'?career.ucHistory:key==='fa'?career.faHistory:career.cupHistory)||[];if(!['premier','first','second'].includes(key)){recent=recent.filter(x=>x.winner).map(x=>({year:1998+x.season,club:x.winner}));const state=cupState(id);if(state?.winner)recent.push({year:1998+career.season,club:state.winner});}const rows=[...history,...recent].sort((a,b)=>b.year-a.year),row=x=>`<div class="detail-row"><span>${x.year-1}–${String(x.year).slice(-2)}${x.region?' · '+x.region:''}</span><b>${html(x.club?clubName(x.club):x.name)}</b></div>`;return `<details class="competition-history"><summary>Past winners · ${rows.length} titles</summary><p class="compact-note">Historical champions through 1997–98, followed by your career results. Club names use their game counterparts. Regional third-tier titles are labelled North and South.</p>${rows.slice(0,10).map(row).join('')}${rows.length>10?`<details><summary>Earlier winners</summary>${rows.slice(10).map(row).join('')}</details>`:''}</details>`;}

function subPitchRows(){const slots=slotsFor(career.formation),groups=[['ST'],['LW','RW','AM','CM','DM'],['LB','RB','CB'],['GK']];return groups.map(positions=>{const indices=slots.map((p,i)=>positions.includes(p)?i:-1).filter(i=>i>=0);return `<div class="sub-pitch-row" style="--players:${indices.length}">${indices.map(i=>subPlayerCard(match.lineup[i],i)).join('')}</div>`}).join('');}
